if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-1-1","moduleId":"module-1","title":"Understanding Income","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 9: Pathways to earning money","concept":"Classify earned and received income and calculate funds available before a due date."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for understanding income"},{"source":"finscope","section":"7.1 Financial Sufficiency and Decision Making; 7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 6: Exploring Options for Earning Money","concept":"Classify earned and received income and calculate funds available before a due date. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Classify earned and received income and calculate funds available before a due date.","outcomes":["Classify earned and received income and calculate funds available before a due date."],"situation":{"title":"Understanding Income in student life","body":"Mwila studies in Kitwe. K400 from her aunt has reached her mobile-money wallet and she has received K150 for tutoring. Another K300 is expected next week. Accommodation of K500 is due tomorrow. The expected payment has not arrived. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Income is money coming in, such as pay for work or support received. Earned income comes from work or business; received support may be a gift or allowance. Either may be regular or irregular. A promised payment is expected income, not money available today. Write down the source, amount, arrival date and confidence in that date. Borrowed money increases cash but creates a repayment obligation; it is not earnings. For a small trading business, sales receipts are not all profit because stock and other costs must be covered.","takeaway":"Distinguish earned money from received support.","definitions":[{"term":"Earned income","meaning":"Money obtained through work or business activity.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Received support","meaning":"Money provided without working for it, such as a family gift.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Available funds","meaning":"Confirmed money accessible when a payment is due.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Separate sources: K150 tutoring is earned; K400 family support is received.","Add confirmed funds: K400 + K150 = K550. Exclude the K300 promise.","After K500 accommodation, K50 remains. Review food and transport needs before making another commitment."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"How should Mwila classify her money and plan tomorrow’s payment?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Distinguish earned money from received support.","consequence":"After K500 accommodation, K50 remains. Review food and transport needs before making another commitment.","options":[{"text":"K150 earned, K400 received; K550 available","feedback":"Both confirmed amounts can be used now. The promised K300 cannot yet cover a bill."},{"text":"K850 available because all three payments count","feedback":"K300 is still expected. Counting it now hides a timing shortfall."},{"text":"Only K150 counts because family support is not earned","feedback":"Received support still provides usable funds once it arrives."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"Both confirmed amounts can be used now. The promised K300 cannot yet cover a bill.","low":"K300 is still expected. Counting it now hides a timing shortfall.","high":"Received support still provides usable funds once it arrives."}},"checkpoint":[{"id":"lesson-1-1-q1","prompt":"Which is irregular earned income?","options":[{"text":"Occasional paid tutoring","feedback":"Payment for work is earned, even when dates and amounts vary."},{"text":"A fixed family gift","feedback":"This is received support, not pay for work."},{"text":"A loan from a friend","feedback":"A loan must be repaid; it is not earnings."}],"correct":0,"explanation":"Payment for work is earned, even when dates and amounts vary."},{"id":"lesson-1-1-q2","prompt":"K240 is in cash, K160 has arrived in a wallet and K200 is promised. What is available now?","options":[{"text":"K600","feedback":"K200 has not arrived."},{"text":"K160","feedback":"Accessible cash also counts."},{"text":"K400","feedback":"K240 + K160 = K400; exclude the promise."}],"correct":2,"explanation":"K240 + K160 = K400; exclude the promise."},{"id":"lesson-1-1-q3","prompt":"Support is delayed and rent is due. What is a useful next step?","options":[{"text":"Assume all irregular income will stop forever","feedback":"A delay is uncertainty to plan for, not proof that no future income will arrive."},{"text":"Check available funds and discuss timing with the landlord","feedback":"Communicating early and checking the shortfall makes the constraint visible."},{"text":"Record the promise as received","feedback":"An entry cannot make delayed money available."}],"correct":1,"explanation":"Communicating early and checking the shortfall makes the constraint visible."}],"summaryTitle":"Bring the ideas together","takeaways":["Distinguish earned money from received support.","Use confirmed funds for immediate commitments.","Plan dates as well as amounts."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
