if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-1-2","moduleId":"module-1","title":"Needs, Wants and Financial Priorities","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 4: Savings plan and spending decision","concept":"Rank competing costs and explain the opportunity cost of a choice."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for needs, wants and financial priorities"},{"source":"finscope","section":"7.1 Financial Sufficiency and Decision Making; 7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 8: Know the Difference Between Needs and Wants","concept":"Rank competing costs and explain the opportunity cost of a choice. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Rank competing costs and explain the opportunity cost of a choice.","outcomes":["Rank competing costs and explain the opportunity cost of a choice."],"situation":{"title":"Needs, Wants and Financial Priorities in student life","body":"In Kabwe, Natasha has K180 until Friday. Lecture transport costs K80, assignment data K60 and an outing K100. Her friends want an answer today. Walking is not safe on her route and the assignment is due tomorrow. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A need supports essential living or an important obligation; a want adds enjoyment or convenience. Context matters: data can be essential for an assignment but discretionary for entertainment. Prioritise the consequence and due date, not the label alone. Opportunity cost is the best alternative you give up when using limited money. Peer pressure can make a purchase feel urgent without changing what it costs. Enjoyment is legitimate, but a plan should make the trade-off visible.","takeaway":"Assess needs in context.","definitions":[{"term":"Priority","meaning":"A cost placed ahead of another because of its consequence or urgency.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Opportunity cost","meaning":"The best alternative forgone when making a choice.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Transport plus data costs K80 + K60 = K140.","K180 − K140 = K40 remains. The K100 outing would create a K60 gap.","Natasha can protect coursework and suggest a free meeting. Another student with safe free transport could reasonably choose differently."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which ranking fits Natasha’s stated circumstances?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Assess needs in context.","consequence":"Natasha can protect coursework and suggest a free meeting. Another student with safe free transport could reasonably choose differently.","options":[{"text":"Transport and assignment data first; suggest a free gathering","feedback":"This protects attendance and the deadline while keeping a social option."},{"text":"Outing first, then K80 transport","feedback":"K180 is exhausted and no assignment data is funded."},{"text":"Always remove data because phones are wants","feedback":"Here the data supports a required assignment. Context changes the priority."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This protects attendance and the deadline while keeping a social option.","low":"K180 is exhausted and no assignment data is funded.","high":"Here the data supports a required assignment. Context changes the priority."}},"checkpoint":[{"id":"lesson-1-2-q1","prompt":"What determines whether data is a need in this scenario?","options":[{"text":"Whether the phone is new","feedback":"The device age does not determine the purpose of this purchase."},{"text":"Whether friends buy it","feedback":"Other people’s choices do not establish this student’s needs."},{"text":"Its role in completing required coursework","feedback":"The purpose and consequences matter."}],"correct":2,"explanation":"The purpose and consequences matter."},{"id":"lesson-1-2-q2","prompt":"K250 is available; essential costs are K190. What remains for other choices?","options":[{"text":"K440","feedback":"Adding costs to funds does not show what remains."},{"text":"K60","feedback":"K250 − K190 = K60."},{"text":"K190","feedback":"That is already committed."}],"correct":1,"explanation":"K250 − K190 = K60."},{"id":"lesson-1-2-q3","prompt":"Buying an outing means giving up needed printing. What is the opportunity cost?","options":[{"text":"The printing that cannot now be purchased","feedback":"It is the alternative given up."},{"text":"The total money ever received","feedback":"Opportunity cost concerns this choice, not all past income."},{"text":"Nothing, because the outing is enjoyable","feedback":"Enjoyable choices still use scarce resources."}],"correct":0,"explanation":"It is the alternative given up."}],"summaryTitle":"Bring the ideas together","takeaways":["Assess needs in context.","Rank consequences and deadlines.","Name what a choice would displace."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
