if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-1-3","moduleId":"module-1","title":"Understanding Expenses","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 7: Budget and budgeting","concept":"Categorise recurring and occasional costs and calculate their combined total."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for understanding expenses"},{"source":"finscope","section":"7.1 Financial Sufficiency and Decision Making; 7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 9: Control Spending","concept":"Categorise recurring and occasional costs and calculate their combined total. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Categorise recurring and occasional costs and calculate their combined total.","outcomes":["Categorise recurring and occasional costs and calculate their combined total."],"situation":{"title":"Understanding Expenses in student life","body":"Chanda pays K300 accommodation each month in Ndola. During a study week he buys five K20 lunches, four K15 minibus trips and K40 printing. Each payment feels small, but he has not added them together. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"An expense is money used for a good, service or obligation. Fixed expenses stay broadly stable over a chosen period; variable expenses change with usage or prices. Frequency is a separate question: a variable cost may recur daily, while a fixed examination fee may occur once. Record the amount, date, category and purpose soon after payment. Categories help you see patterns; they are not judgements about a person.","takeaway":"Separate amount stability from frequency.","definitions":[{"term":"Fixed expense","meaning":"A cost that is broadly stable for the planned period.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Variable expense","meaning":"A cost that changes with consumption or circumstances.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Occasional expense","meaning":"A cost that does not occur every regular budget period.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Five lunches: 5 × K20 = K100.","Four trips: 4 × K15 = K60. Printing: K40.","Weekly purchases total K100 + K60 + K40 = K200. Keep monthly accommodation separate until comparing the same period."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which record accurately describes the week?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Separate amount stability from frequency.","consequence":"Weekly purchases total K100 + K60 + K40 = K200. Keep monthly accommodation separate until comparing the same period.","options":[{"text":"Food K100, transport K60, study materials K40; total K200","feedback":"The record captures every purchase once under useful categories."},{"text":"Food K20, transport K15, printing K40; total K75","feedback":"This counts only one lunch and one trip."},{"text":"Accommodation K300 is the weekly purchase total","feedback":"Accommodation is a separate monthly obligation, not these weekly purchases."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The record captures every purchase once under useful categories.","low":"This counts only one lunch and one trip.","high":"Accommodation is a separate monthly obligation, not these weekly purchases."}},"checkpoint":[{"id":"lesson-1-3-q1","prompt":"Can an expense be both variable and regular?","options":[{"text":"Only if paid through a bank","feedback":"Payment method does not determine cost frequency."},{"text":"Yes, daily transport can vary by number of trips","feedback":"Frequency and amount stability are different dimensions."},{"text":"No, regular always means fixed","feedback":"A repeated payment may change in amount."}],"correct":1,"explanation":"Frequency and amount stability are different dimensions."},{"id":"lesson-1-3-q2","prompt":"Three K12 snacks and K24 printing total how much?","options":[{"text":"K60","feedback":"3 × K12 + K24 = K60."},{"text":"K36","feedback":"That omits printing."},{"text":"K48","feedback":"That counts only two snacks."}],"correct":0,"explanation":"3 × K12 + K24 = K60."},{"id":"lesson-1-3-q3","prompt":"Why keep dates when recording costs?","options":[{"text":"To make the spending disappear","feedback":"Recording improves visibility but does not undo a payment."},{"text":"To prove all small purchases are bad","feedback":"Small purchases have different purposes; records support informed choices."},{"text":"To compare spending within the correct budget period","feedback":"Dates prevent mixing a week’s costs with a different month."}],"correct":2,"explanation":"Dates prevent mixing a week’s costs with a different month."}],"summaryTitle":"Bring the ideas together","takeaways":["Separate amount stability from frequency.","Add repeated small costs.","Record dates and categories consistently."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
