if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-1-4","moduleId":"module-1","title":"Making Everyday Money Decisions","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 8: Financial negotiations","concept":"Evaluate an obligation and communicate a financial boundary respectfully."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for making everyday money decisions"},{"source":"finscope","section":"7.1 Financial Sufficiency and Decision Making; 7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 15–17: Talking About Money; Resolving Conflicts About Money","concept":"Evaluate an obligation and communicate a financial boundary respectfully. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Evaluate an obligation and communicate a financial boundary respectfully.","outcomes":["Evaluate an obligation and communicate a financial boundary respectfully."],"situation":{"title":"Making Everyday Money Decisions in student life","body":"Leya holds K240 for shared electricity with two roommates. A roommate asks to borrow K150 for a personal purchase and promises to repay next week. The electricity payment is due tonight and the money belongs to the household plan. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"An obligation is a payment or responsibility already agreed. A balance can contain money reserved for someone else or for an essential bill. Before lending, ask whose money it is, when it is needed, and what happens if repayment is late. A respectful boundary can explain the commitment and offer a non-financial alternative. Supporting family or friends is a valid priority, but uncertainty and the effects on others should be discussed openly.","takeaway":"Check commitments before lending.","definitions":[{"term":"Committed funds","meaning":"Money already reserved for an obligation.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Financial boundary","meaning":"A clear limit on what money or responsibility you can offer.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["K240 is available but all K240 is committed to electricity.","Lending K150 leaves K90, a K150 gap tonight.","“This is our electricity money and it is due tonight. I cannot lend it. I can help you consider another option.” This protects the shared agreement without attacking the roommate."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which response protects the shared obligation?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Check commitments before lending.","consequence":"“This is our electricity money and it is due tonight. I cannot lend it. I can help you consider another option.” This protects the shared agreement without attacking the roommate.","options":[{"text":"Explain the electricity commitment and decline this loan","feedback":"A clear explanation protects the household and preserves a respectful conversation."},{"text":"Lend it without telling the other roommate","feedback":"This shifts a K150 shortfall onto others without their agreement."},{"text":"Agree because a repayment promise removes all risk","feedback":"A promise next week cannot fund tonight’s electricity."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"A clear explanation protects the household and preserves a respectful conversation.","low":"This shifts a K150 shortfall onto others without their agreement.","high":"A promise next week cannot fund tonight’s electricity."}},"checkpoint":[{"id":"lesson-1-4-q1","prompt":"What makes funds committed?","options":[{"text":"They are reserved for an agreed obligation","feedback":"Their purpose matters even while they remain in the wallet."},{"text":"They are held in cash","feedback":"Cash can be committed or uncommitted."},{"text":"They appear in a large balance","feedback":"The size of a balance does not show its obligations."}],"correct":0,"explanation":"Their purpose matters even while they remain in the wallet."},{"id":"lesson-1-4-q2","prompt":"K500 includes K420 reserved for rent. How much is uncommitted?","options":[{"text":"K500","feedback":"This ignores rent."},{"text":"K920","feedback":"Adding the obligation does not create funds."},{"text":"K80","feedback":"K500 − K420 = K80."}],"correct":2,"explanation":"K500 − K420 = K80."},{"id":"lesson-1-4-q3","prompt":"A relative requests support that would prevent buying essential medicine. What is reasonable?","options":[{"text":"Assume every request must be met in full","feedback":"Requests must be considered alongside available resources and obligations."},{"text":"Explain the limit and discuss a smaller or non-cash form of help","feedback":"Boundaries can recognise both care and essential needs."},{"text":"Hide the medicine cost to avoid discussion","feedback":"Hiding the constraint makes the trade-off harder to resolve."}],"correct":1,"explanation":"Boundaries can recognise both care and essential needs."}],"summaryTitle":"Bring the ideas together","takeaways":["Check commitments before lending.","Consider who bears the consequences.","Communicate limits respectfully and early."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
