if lid is null then lid:='cfec8bfd-9702-4589-aecd-a614a729c063'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Planning Your Monthly Allowance','',2); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-2-2","moduleId":"module-2","title":"Planning Your Monthly Allowance","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 7: Budget and budgeting","concept":"Allocate confirmed money and revise the plan when later support is delayed."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for planning your monthly allowance"},{"source":"finscope","section":"7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 10: Think About the Future: Money In and Money Out","concept":"Allocate confirmed money and revise the plan when later support is delayed. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Allocate confirmed money and revise the plan when later support is delayed.","outcomes":["Allocate confirmed money and revise the plan when later support is delayed."],"situation":{"title":"Planning Your Monthly Allowance in student life","body":"Mutinta rents near campus in Livingstone. K900 has arrived and K600 is expected mid-month. Her full plan is accommodation K600, food K400, transport K200, data K100 and study materials K100. The second payment is delayed. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A budget period is the span your plan covers. Planned income records what you anticipate; confirmed income records what actually arrived. Allocate essentials with their due dates before optional costs. A monthly plan may need weekly cash-flow checks when support arrives in parts. Unallocated money is the planned income minus allocations, not proof that the same cash is already available. When essentials exceed confirmed funds, identify the gap and discuss timing or support; a budget cannot manufacture income.","takeaway":"Separate expected income from received money.","definitions":[{"term":"Allocation","meaning":"An amount set aside for a category.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Cash-flow timing","meaning":"When money arrives relative to when costs are due.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Full allocations: K600 + K400 + K200 + K100 + K100 = K1,400 against K1,500 expected.","With only K900 confirmed, full allocations exceed available money by K500.","A first-period plan could reserve K600 rent, K150 food, K80 transport, K40 data and K30 materials: exactly K900. This is feasible only if reduced amounts cover the period; discuss any remaining essential gap."],"showBudgetTable":false},"practice":{"kind":"allocation","prompt":"Revise Mutinta’s allocations after the delay","context":"Only K900 is available now. Plan for the immediate period: accommodation needs K600, food at least K120, transport at least K60, data at least K30 and study materials at least K20. Allocate all five categories; you may keep some money unallocated. These reduced needs cover only this first period, not the full month.","correct":0,"unit":"K","allocation":{"available":900,"fields":[{"id":"accommodation","label":"Accommodation","minimum":600},{"id":"food","label":"Food","minimum":120},{"id":"transport","label":"Transport","minimum":60},{"id":"data","label":"Data","minimum":30},{"id":"materials","label":"Study materials","minimum":20}]},"hint":"The minimum immediate needs total K830. Decide how to use or reserve the remaining K70. The delayed K600 is not available yet.","consequence":"This is a temporary plan. Compare it with the full K1,400 monthly needs and revisit the remaining period when support arrives. If it does not arrive, discuss unmet essentials and timing; a budget cannot create income.","feedback":{"correctTitle":"Your plan fits the immediate constraints","incorrectTitle":"Review the plan’s gaps","correct":"","low":"","high":""}},"checkpoint":[{"id":"lesson-2-2-q1","prompt":"What is a budget allocation?","options":[{"text":"A payment already made","feedback":"An allocation is a plan; a transaction records an actual payment."},{"text":"A guaranteed future transfer","feedback":"A plan does not guarantee incoming support."},{"text":"Money planned for a category","feedback":"An allocation gives a planned purpose to funds."}],"correct":2,"explanation":"An allocation gives a planned purpose to funds."},{"id":"lesson-2-2-q2","prompt":"Planned income is K1,200 and allocations are K1,050. How much is unallocated?","options":[{"text":"K2,250","feedback":"Adding allocations does not produce a remainder."},{"text":"K150","feedback":"K1,200 − K1,050 = K150 planned remainder."},{"text":"K1,050","feedback":"That is allocated."}],"correct":1,"explanation":"K1,200 − K1,050 = K150 planned remainder."},{"id":"lesson-2-2-q3","prompt":"Which plan handles irregular support best?","options":[{"text":"Use due dates and revise when payments arrive or change","feedback":"Dates connect the monthly plan to immediate commitments."},{"text":"Spend expected income before it arrives","feedback":"This can create a cash shortfall."},{"text":"Avoid budgeting until income becomes regular","feedback":"A flexible plan can be useful precisely because income is irregular."}],"correct":0,"explanation":"Dates connect the monthly plan to immediate commitments."}],"summaryTitle":"Bring the ideas together","takeaways":["Separate expected income from received money.","Allocate essentials by due date.","Revisit the plan when support changes."],"action":{"actionType":"open_budget","destination":"create","label":"Create My Budget","optional":true}}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
