if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-2-4","moduleId":"module-2","title":"Adjusting a Budget","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 7: Budget and budgeting","concept":"Calculate a variance and revise allocations while preserving essential costs."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for adjusting a budget"},{"source":"finscope","section":"7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 10: Think About the Future: Money In and Money Out","concept":"Calculate a variance and revise allocations while preserving essential costs. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Calculate a variance and revise allocations while preserving essential costs.","outcomes":["Calculate a variance and revise allocations while preserving essential costs."],"situation":{"title":"Adjusting a Budget in student life","body":"In Mongu, Namakau planned K200 transport but now needs K260. Printing rises from K50 to K90. A K100 leisure allocation is still unspent, and expected family support has not arrived. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A variance is the difference between planned and actual or newly forecast spending. State the direction: spending above the plan requires more funding. Review whether a change is temporary or likely to continue. Contingencies reserve room for uncertainty. You can move unspent optional allocations, change timing where safe, or seek support. Do not lower already-spent amounts on paper or remove unavoidable needs just to display a balanced plan.","takeaway":"Calculate what changed.","definitions":[{"term":"Variance","meaning":"The difference between an allocation and actual or revised spending.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Contingency","meaning":"An amount or alternative plan for uncertain costs.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Transport needs K260 − K200 = K60 extra.","Printing needs K90 − K50 = K40 extra. Combined increase: K100.","Moving the unspent K100 leisure allocation covers the increase. If it had already been spent, this change would not create cash."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which revision covers the two increases?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Calculate what changed.","consequence":"Moving the unspent K100 leisure allocation covers the increase. If it had already been spent, this change would not create cash.","options":[{"text":"Move K100 of unspent leisure funds to transport and printing","feedback":"K60 + K40 = K100 and the source is still unspent."},{"text":"Reduce recorded transport payments to K200","feedback":"Changing records cannot undo actual expenditure."},{"text":"Spend the delayed support as though received","feedback":"Expected funds are not yet available."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"K60 + K40 = K100 and the source is still unspent.","low":"Changing records cannot undo actual expenditure.","high":"Expected funds are not yet available."}},"checkpoint":[{"id":"lesson-2-4-q1","prompt":"Spending K150 against K120 planned means what?","options":[{"text":"K30 above allocation","feedback":"K150 − K120 = K30 over the plan."},{"text":"K30 still unspent","feedback":"Actual spending already exceeds the plan."},{"text":"K270 available","feedback":"Adding planned and actual figures is not a balance."}],"correct":0,"explanation":"K150 − K120 = K30 over the plan."},{"id":"lesson-2-4-q2","prompt":"A K70 shortfall and K45 unspent optional allocation leave what gap?","options":[{"text":"K115","feedback":"Moving funds reduces the gap rather than adding to it."},{"text":"No gap","feedback":"K45 does not cover K70."},{"text":"K25","feedback":"K70 − K45 = K25 still to address."}],"correct":2,"explanation":"K70 − K45 = K25 still to address."},{"id":"lesson-2-4-q3","prompt":"Essential costs exceed all confirmed resources. What does a useful review do?","options":[{"text":"Hide the largest essential bill","feedback":"Omitting it conceals the unmet need."},{"text":"Identify the gap and explore timing or support without blame","feedback":"A budget reveals constraints; low income is not always solved by cutting."},{"text":"Promise the budget will solve the shortage","feedback":"Planning cannot guarantee more resources."}],"correct":1,"explanation":"A budget reveals constraints; low income is not always solved by cutting."}],"summaryTitle":"Bring the ideas together","takeaways":["Calculate what changed.","Move only funds that remain available.","Make unmet essential needs visible."],"action":{"actionType":"open_budget","destination":"overview","label":"Review My Budget","optional":true}}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-2-4',title='Adjusting a Budget',summary='Calculate a variance and revise allocations while preserving essential costs.',structured_content='{"id":"lesson-2-4","moduleId":"module-2","title":"Adjusting a Budget","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 7: Budget and budgeting","concept":"Calculate a variance and revise allocations while preserving essential costs."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for adjusting a budget"},{"source":"finscope","section":"7.2 Cash-flow Management","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 10: Think About the Future: Money In and Money Out","concept":"Calculate a variance and revise allocations while preserving essential costs. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Calculate a variance and revise allocations while preserving essential costs.","outcomes":["Calculate a variance and revise allocations while preserving essential costs."],"situation":{"title":"Adjusting a Budget in student life","body":"In Mongu, Namakau planned K200 transport but now needs K260. Printing rises from K50 to K90. A K100 leisure allocation is still unspent, and expected family support has not arrived. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and 