if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-3-1","moduleId":"module-3","title":"Why People Save","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 3: Savings and savings options","concept":"Distinguish saving purposes and assess a realistic contribution."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for why people save"},{"source":"finscope","section":"9.2 Savings; 7.3 Risk Management; 6.1.4.1 Chilimba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 2: Why Save?","concept":"Distinguish saving purposes and assess a realistic contribution. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Distinguish saving purposes and assess a realistic contribution.","outcomes":["Distinguish saving purposes and assess a realistic contribution."],"situation":{"title":"Why People Save in student life","body":"Bupe’s family sends support after crop sales near Chipata. This month K800 arrives. K750 is needed for food, accommodation and study costs. Next month’s support is uncertain. Bupe wonders whether saving must mean putting away a large fixed amount. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Saving keeps money for later use. Purposes include a known future cost, a goal and an unexpected need. Financial resilience is the capacity to cope with setbacks; savings can help but are not its only source. Saving capacity depends on resources after essential needs and obligations. A small flexible contribution can be useful; if there is no surplus, protecting essential needs and seeking support may be the realistic response.","takeaway":"Give savings a purpose.","definitions":[{"term":"Savings","meaning":"Money retained for future use.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Saving capacity","meaning":"What can realistically be set aside after considering commitments.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Confirmed funds K800 minus essential commitments K750 leave K50.","K50 is the maximum uncommitted amount in this simple example, not a required contribution.","Bupe might reserve K30 for next month and K20 for a near-term uncertain cost. If food costs rise K50, saving may need to pause."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which saving approach fits Bupe’s uncertainty?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Give savings a purpose.","consequence":"Bupe might reserve K30 for next month and K20 for a near-term uncertain cost. If food costs rise K50, saving may need to pause.","options":[{"text":"Consider a contribution within K50 while protecting essential needs","feedback":"The plan starts with capacity and allows it to change."},{"text":"Save K200 even if food cannot be covered","feedback":"K200 exceeds the uncommitted funds."},{"text":"Treat irregular income as proof saving is pointless","feedback":"Flexible saving may help when a surplus exists, even if it is not monthly."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The plan starts with capacity and allows it to change.","low":"K200 exceeds the uncommitted funds.","high":"Flexible saving may help when a surplus exists, even if it is not monthly."}},"checkpoint":[{"id":"lesson-3-1-q1","prompt":"Which is a planned saving purpose?","options":[{"text":"Replacing a receipt after a payment","feedback":"Record keeping is useful but is not retaining money."},{"text":"Counting a loan as savings profit","feedback":"Borrowed funds carry a repayment obligation."},{"text":"Setting aside money for a known examination fee","feedback":"The fee is a foreseeable future expense."}],"correct":2,"explanation":"The fee is a foreseeable future expense."},{"id":"lesson-3-1-q2","prompt":"K600 arrives and essential commitments are K580. What is uncommitted?","options":[{"text":"K120","feedback":"There is no basis for that amount."},{"text":"K20","feedback":"K600 − K580 = K20."},{"text":"K580","feedback":"That is needed for commitments."}],"correct":1,"explanation":"K600 − K580 = K20."},{"id":"lesson-3-1-q3","prompt":"There is no money left after basic needs. What is a fair response?","options":[{"text":"Pause saving and review support or income options","feedback":"Saving capacity may be zero; this is not a personal failure."},{"text":"Skip necessary food to meet a fixed target","feedback":"A target should not automatically override essential needs."},{"text":"Invent a savings balance for motivation","feedback":"A false record cannot fund a future need."}],"correct":0,"explanation":"Saving capacity may be zero; this is not a personal failure."}],"summaryTitle":"Bring the ideas together","takeaways":["Give savings a purpose.","Base contributions on actual capacity.","Adapt to irregular support without blame."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-3-1',title='Why People Save',summary='Distinguish saving purposes and assess a realistic contribution.',structured_content='{"id":"lesson-3-1","moduleId":"module-3","title":"Why People Save","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 3: Savings and savings options","concept":"Distinguish saving purposes and assess a realistic contribution."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for why people save"},{"source":"finscope","section":"9.2 Savings; 7.3 Risk Management; 6.1.4.1 Chilimba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 2: Why Save?","concept":"Distinguish saving purposes and assess a realistic contribution. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Distinguish saving purposes and assess a realistic contribution.","outcomes":["Distinguish saving purposes and assess a realistic contribution."],"situation":{"title":"Why People Save in student life","body":"Bupe’s family sends support after crop sales near Chipata. This month K800 arrives. K750 is needed for food, accommodation and study costs. Next month’s support is uncertain. Bupe wonders whether saving must mean putting away a large fixed amount. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Saving keeps money for later use. Purposes include a known future cost, a goal and an unexpected need. Financial resilience is the capacity to cope with setbacks; savings can help but are not its only source. Saving capacity depends on resources after essential needs and obligations. A small flexible contribution can be useful; if there is no surplus, protecting essential needs and seeking support may be the realistic response.","takeaway":"Give savings a purpose.","definitions":[{"term":"Savings","meaning":"Money retained for future use.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Saving capacity","meaning":"What can realistically be set aside after considering commitments.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Confirmed funds K800 minus essential commitments K750 leave K50.","K50 is the maximum uncommitted amount in this simple example, not a required contribution.","Bupe might reserve K30 for next month and K20 for a near-term uncertain cost. If food costs rise K50, saving may need to pause."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which saving approach fits Bupe’s uncertainty?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Give savings a purpose.","consequence":"Bupe might reserve K30 for next month and K20 for a near-term uncertain cost. If food costs rise K50, saving may need to pause.","options":[{"text":"Consider a contribution within K50 while protecting essential needs","feedback":"The plan starts with capacity and allows it to change."},{"text":"Save K200 even if food cannot be covered","feedback":"K200 exceeds the uncommitted funds."},{"text":"Treat irregular income as proof saving is pointless","feedback":"Flexible saving may help when a surplus exists, even if it is not monthly."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The plan starts with capacity and allows it to change.","low":"K200 exceeds the uncommitted funds.","high":"Flexible saving may help when a surplus exists, even if it is not monthly."}},"checkpoint":[{"id":"lesson-3-1-q1","prompt":"Which is a planned saving purpose?","options":[{"text":"Replacing a receipt after a payment","feedback":"Record keeping is useful but is not retaining money."},{"text":"Counting a loan as savings profit","feedback":"Borrowed funds carry a repayment obligation."},{"text":"Setting aside money for a known examination fee","feedback":"The fee is a foreseeable future expense."}],"correct":2,"explanation":"The fee is a foreseeable future expense."},{"id":"lesson-3-1-q2","prompt":"K600 arrives and essential commitments are K580. What is uncommitted?","options":[{"text":"K120","feedback":"There is no basis for that amount."},{"text":"K20","feedback":"K600 − K580 = K20."},{"text":"K580","feedback":"That is needed for commitments."}],"correct":1,"explanation":"K600 − K580 = K20."},{"id":"lesson-3-1-q3","prompt":"There is no money left after basic needs. What is a fair response?","options":[{"text":"Pause saving and review support or income options","feedback":"Saving capacity may be zero; this is not a personal failure."},{"text":"Skip necessary food to meet a fixed target","feedback":"A target should not automatically override essential needs."},{"text":"Invent a savings balance for motivation","feedback":"A false record cannot fund a future need."}],"correct":0,"explanation":"Saving capacity may be zero; this is not a personal failure."}],"summaryTitle":"Bring the ideas together","takeaways":["Give savings a purpose.","Base contributions on actual capacity.","Adapt to irregular support without blame."]}'::jsonb,content='Saving keeps money for later use. Purposes include a known future cost, a goal and an unexpected need. Financial resilience is the capacity to cope with setbacks; savings can help but are not its only source. Saving capacity depends on resources after essential needs and obligations. A small flexible contribution can be useful; if there is no surplus, protecting essential needs and seeking support may be the realistic response.',revision=1,estimated_minutes=10,is_published=true where id=lid;
