if lid is null then lid:='602d7648-f239-4325-a621-a8d08f610181'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Setting Financial Goals','',2); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-3-2","moduleId":"module-3","title":"Setting Financial Goals","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 2: Financial goals setting","concept":"Calculate a contribution from a target, existing savings and deadline."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for setting financial goals"},{"source":"finscope","section":"9.2 Savings; 7.3 Risk Management; 6.1.4.1 Chilimba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 3–4: Choose a Savings Goal; Make a Savings Plan","concept":"Calculate a contribution from a target, existing savings and deadline. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Calculate a contribution from a target, existing savings and deadline.","outcomes":["Calculate a contribution from a target, existing savings and deadline."],"situation":{"title":"Setting Financial Goals in student life","body":"Misozi needs a more reliable phone for coursework. A fictional replacement costs K1,200. She has K300 saved and hopes to buy it in six months, but her part-time work varies. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A useful goal names the purpose, target amount and deadline. Subtract existing savings before dividing the remaining target by contribution periods. Compare the result with realistic capacity. If it is too high, consider a later date, a less costly suitable item or a different income plan. Review the goal as prices and circumstances change; a deadline is a planning tool, not a moral test.","takeaway":"Specify amount, purpose and deadline.","definitions":[{"term":"Target","meaning":"The amount needed for a specific purpose.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Contribution","meaning":"An amount added towards the target during a period.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Remaining target: K1,200 − K300 = K900.","Six monthly contributions: K900 ÷ 6 = K150 per month.","If only K100 per month is affordable, K900 ÷ K100 = 9 months, assuming the target price stays unchanged."],"showBudgetTable":false},"practice":{"kind":"numeric","prompt":"How much would Misozi need to save each month?","context":"The phone target is K1,200, existing savings are K300 and the deadline is six months. Calculate the monthly contribution before checking whether it is affordable.","correct":150,"explanation":"(K1,200 − K300) ÷ 6 = K150 each month. If only K100 is affordable, extend the remaining K900 target to nine months or review the item and costs.","unit":"K","hint":"Write down the known amounts, then choose the operations. Include all stated costs.","consequence":"(K1,200 − K300) ÷ 6 = K150 each month. If only K100 is affordable, extend the remaining K900 target to nine months or review the item and costs.","feedback":{"correctTitle":"The calculation is consistent","incorrectTitle":"Recheck the amounts","correct":"(K1,200 − K300) ÷ 6 = K150 each month. If only K100 is affordable, extend the remaining K900 target to nine months or review the item and costs.","low":"Your answer is below the required amount. (K1,200 − K300) ÷ 6 = K150 each month. If only K100 is affordable, extend the remaining K900 target to nine months or review the item and costs.","high":"Your answer is above the required amount. (K1,200 − K300) ÷ 6 = K150 each month. If only K100 is affordable, extend the remaining K900 target to nine months or review the item and costs."}},"checkpoint":[{"id":"lesson-3-2-q1","prompt":"Which goal is most specific?","options":[{"text":"Spend less somehow","feedback":"This does not define a measurable goal."},{"text":"Save K400 for study materials by the start of next term","feedback":"It identifies amount, purpose and deadline."},{"text":"Become rich soon","feedback":"Neither amount nor deadline is clear."}],"correct":1,"explanation":"It identifies amount, purpose and deadline."},{"id":"lesson-3-2-q2","prompt":"A K900 target, K300 already saved and four months require what monthly contribution?","options":[{"text":"K150","feedback":"(K900 − K300) ÷ 4 = K150."},{"text":"K225","feedback":"That ignores existing savings."},{"text":"K600","feedback":"That is the remaining total, not the monthly amount."}],"correct":0,"explanation":"(K900 − K300) ÷ 4 = K150."},{"id":"lesson-3-2-q3","prompt":"The target item increases in price. What should happen?","options":[{"text":"Keep the old target without checking","feedback":"The old total may no longer buy the item."},{"text":"Borrow automatically to preserve the date","feedback":"Borrowing creates a separate affordability decision."},{"text":"Recalculate and compare a revised target or deadline","feedback":"A plan should reflect changed costs and capacity."}],"correct":2,"explanation":"A plan should reflect changed costs and capacity."}],"summaryTitle":"Bring the ideas together","takeaways":["Specify amount, purpose and deadline.","Subtract existing savings first.","Adjust the goal when capacity changes."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
