if lid is null then lid:='f3a5dfee-2134-4451-a0ec-410d2136f106'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Choosing Where to Save','',3); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-3-3","moduleId":"module-3","title":"Choosing Where to Save","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 3: Savings and savings options","concept":"Compare saving options using access, security and conditions."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for choosing where to save"},{"source":"finscope","section":"9.2 Savings; 7.3 Risk Management; 6.1.4.1 Chilimba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 12: Save in a Safe Place","concept":"Compare saving options using access, security and conditions. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Compare saving options using access, security and conditions.","outcomes":["Compare saving options using access, security and conditions."],"situation":{"title":"Choosing Where to Save in student life","body":"Ruth needs K300 available for possible travel at short notice. She compares cash at home, mobile money, a bank account and a chilimba whose next payout to her is three months away. She has not checked any product’s charges. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Saving methods differ in liquidity, security, accessibility and costs. Cash is immediately usable but can be lost or stolen. Digital access depends on service availability, account security and access points. Bank terms vary; check charges, withdrawal conditions and relevant protections. A chilimba pools contributions under an agreed arrangement; access depends on the payout schedule and members meeting commitments. Trust matters but does not remove default or record-keeping risk. No single option suits every purpose.","takeaway":"Match saving methods to the purpose.","definitions":[{"term":"Liquidity","meaning":"How readily funds can be accessed when needed.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Informal saving arrangement","meaning":"A savings arrangement organised outside a formal deposit account.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Ruth’s need is immediate access to K300, not a payout months later.","A three-month chilimba payout does not match that timing, even if contributions are convenient.","Compare accessible options using actual terms and secure access. Splitting funds may help access but can add charges or management difficulty."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Ruth prioritise for emergency travel money?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Match saving methods to the purpose.","consequence":"Compare accessible options using actual terms and secure access. Splitting funds may help access but can add charges or management difficulty.","options":[{"text":"Reliable short-notice access and security, after checking actual terms","feedback":"These criteria match the purpose; the cheapest-looking option may have access limits."},{"text":"The option with the most enthusiastic recommendation","feedback":"A recommendation does not establish liquidity or security."},{"text":"A payout only in three months because all savings are identical","feedback":"The payout timing does not match an immediate need."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"These criteria match the purpose; the cheapest-looking option may have access limits.","low":"A recommendation does not establish liquidity or security.","high":"The payout timing does not match an immediate need."}},"checkpoint":[{"id":"lesson-3-3-q1","prompt":"What does liquidity describe?","options":[{"text":"Access to money when it is needed","feedback":"Liquidity concerns timely access."},{"text":"How colourful a banking app is","feedback":"Appearance does not determine access."},{"text":"A guarantee of no losses","feedback":"Liquidity and security are separate considerations."}],"correct":0,"explanation":"Liquidity concerns timely access."},{"id":"lesson-3-3-q2","prompt":"An account requires seven days’ notice, but money is needed tomorrow. What is the mismatch?","options":[{"text":"The balance must be zero","feedback":"A positive balance may still be subject to notice."},{"text":"The account must be fraudulent","feedback":"A disclosed notice period is not itself evidence of fraud."},{"text":"The access condition does not fit the deadline","feedback":"The notice period makes the funds unavailable at the needed time."}],"correct":2,"explanation":"The notice period makes the funds unavailable at the needed time."},{"id":"lesson-3-3-q3","prompt":"Before joining a chilimba, what should you clarify?","options":[{"text":"Nothing if a friend participates","feedback":"Trust does not replace understanding the conditions."},{"text":"Contributions, payout order, records and what happens if someone cannot pay","feedback":"These determine obligations and access risks."},{"text":"Only the name of the group","feedback":"A name does not explain the arrangement."}],"correct":1,"explanation":"These determine obligations and access risks."}],"summaryTitle":"Bring the ideas together","takeaways":["Match saving methods to the purpose.","Compare access, security and charges.","Understand informal arrangements before joining."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
