if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-3-4","moduleId":"module-3","title":"Emergency Savings and Setbacks","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 6: Risk management and insurance","concept":"Plan a response to an unexpected cost and a realistic rebuilding schedule."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for emergency savings and setbacks"},{"source":"finscope","section":"9.2 Savings; 7.3 Risk Management; 6.1.4.1 Chilimba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 13: Dealing with Setbacks in Saving","concept":"Plan a response to an unexpected cost and a realistic rebuilding schedule. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Plan a response to an unexpected cost and a realistic rebuilding schedule.","outcomes":["Plan a response to an unexpected cost and a realistic rebuilding schedule."],"situation":{"title":"Emergency Savings and Setbacks in student life","body":"Kelvin must travel home unexpectedly from Solwezi. The fictional fare is K350. He has K250 reserved for emergencies and K100 in unspent optional money. He also has rent money that must remain available. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"An emergency reserve is intended for urgent unexpected needs, so using it for that purpose is not failure. Check urgency, available resources and alternatives before choosing a response. Protect other essential commitments where possible. After the event, review what remains and rebuild at a pace consistent with current income. There is no universal amount every student can save; a contingency plan can also include trusted support and information about available assistance.","takeaway":"Using emergency savings for emergencies is appropriate.","definitions":[{"term":"Financial shock","meaning":"An unexpected event that changes costs or income.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Rebuilding plan","meaning":"A realistic schedule for restoring used reserves.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["K250 emergency reserve + K100 unspent optional money = K350 fare.","The reserve falls to K0; rent remains protected.","If K50 per month becomes affordable, restoring K250 takes five months. A later shortfall may require revising that schedule."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which response fits Kelvin’s resources?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Using emergency savings for emergencies is appropriate.","consequence":"If K50 per month becomes affordable, restoring K250 takes five months. A later shortfall may require revising that schedule.","options":[{"text":"Use the reserve and optional K100, then plan rebuilding","feedback":"The money covers the emergency without consuming rent funds."},{"text":"Keep the reserve untouched and take any available loan","feedback":"The reserve exists for emergencies; borrowing adds costs that need separate assessment."},{"text":"Use rent money and ignore the due date","feedback":"That moves the emergency into a foreseeable housing shortfall."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The money covers the emergency without consuming rent funds.","low":"The reserve exists for emergencies; borrowing adds costs that need separate assessment.","high":"That moves the emergency into a foreseeable housing shortfall."}},"checkpoint":[{"id":"lesson-3-4-q1","prompt":"What is an emergency reserve for?","options":[{"text":"Only predictable annual fees","feedback":"Known fees can have a separate planned fund."},{"text":"Proving you never need help","feedback":"Reserves may be insufficient; seeking support can still be necessary."},{"text":"Urgent unexpected needs","feedback":"It provides resources when an unplanned cost arises."}],"correct":2,"explanation":"It provides resources when an unplanned cost arises."},{"id":"lesson-3-4-q2","prompt":"Restoring K360 at K60 each month takes how long?","options":[{"text":"Sixty months","feedback":"K60 is the contribution amount, not the number of months."},{"text":"Six months","feedback":"K360 ÷ K60 = 6."},{"text":"Three months","feedback":"Three contributions total only K180."}],"correct":1,"explanation":"K360 ÷ K60 = 6."},{"id":"lesson-3-4-q3","prompt":"After a setback, income falls further. What is reasonable?","options":[{"text":"Reduce or pause rebuilding while reviewing essentials","feedback":"Rebuilding should respond to actual capacity."},{"text":"Maintain contributions regardless of food needs","feedback":"This can worsen immediate hardship."},{"text":"Record a reserve that does not exist","feedback":"A fictional balance cannot help in the next emergency."}],"correct":0,"explanation":"Rebuilding should respond to actual capacity."}],"summaryTitle":"Bring the ideas together","takeaways":["Using emergency savings for emergencies is appropriate.","Review essential obligations before choosing a response.","Rebuild according to current capacity."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
