if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-4-1","moduleId":"module-4","title":"Understanding Borrowing","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 5: Equity or debt financing","concept":"Distinguish gifts from loans and identify repayment obligations."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for understanding borrowing"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Session 14: Your Own Money vs. Someone Else’s Money","concept":"Distinguish gifts from loans and identify repayment obligations. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Distinguish gifts from loans and identify repayment obligations.","outcomes":["Distinguish gifts from loans and identify repayment obligations."],"situation":{"title":"Understanding Borrowing in student life","body":"Peter needs K200 for academic materials. A relative offers K100 as a gift, a friend offers K100 repayable in two weeks, and an informal lender offers K200 with unclear conditions. Peter has heard the term kaloba but has not asked what the lender expects. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A loan provides money now in exchange for repayment under agreed terms. A gift has no repayment obligation if that is clearly agreed. Principal is the amount borrowed; repayment may include additional costs. Formal and informal borrowing can both create obligations. With friends or family, clarify whether support is a gift or a loan to avoid conflict. Informal moneylending, sometimes called kaloba, can involve difficult costs or collection practices; do not assume its terms or protections match a regulated lender.","takeaway":"Clarify gift versus loan.","definitions":[{"term":"Principal","meaning":"The original amount borrowed.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Repayment obligation","meaning":"The amount and timing you agree to repay.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Accepting a K100 gift and K100 loan provides K200 now.","Only the K100 loan is repayable under the stated agreement; check whether any charge applies.","The K200 informal offer cannot be compared until total repayment, due date and consequences are clear."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Peter establish before accepting support?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Clarify gift versus loan.","consequence":"The K200 informal offer cannot be compared until total repayment, due date and consequences are clear.","options":[{"text":"Whether it is a gift or loan, the total due and repayment date","feedback":"Clear terms reveal obligations and reduce misunderstandings."},{"text":"Only how quickly he can receive it","feedback":"Speed does not reveal cost or repayment risk."},{"text":"Assume all money from friends is a gift","feedback":"A friend can expect repayment; ask explicitly."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"Clear terms reveal obligations and reduce misunderstandings.","low":"Speed does not reveal cost or repayment risk.","high":"A friend can expect repayment; ask explicitly."}},"checkpoint":[{"id":"lesson-4-1-q1","prompt":"Which statement describes a loan?","options":[{"text":"Any income earned through work","feedback":"Earnings are not automatically repayable."},{"text":"Money provided with an obligation to repay","feedback":"Repayment distinguishes a loan from a clearly agreed gift."},{"text":"Money that is always free","feedback":"Loans may involve interest or charges."}],"correct":1,"explanation":"Repayment distinguishes a loan from a clearly agreed gift."},{"id":"lesson-4-1-q2","prompt":"K300 is borrowed and K340 must be repaid. What is the principal?","options":[{"text":"K300","feedback":"Principal is the original borrowed amount."},{"text":"K40","feedback":"K40 is the additional cost in this example."},{"text":"K340","feedback":"K340 is total repayment."}],"correct":0,"explanation":"Principal is the original borrowed amount."},{"id":"lesson-4-1-q3","prompt":"A lender will not explain repayment terms. What is prudent?","options":[{"text":"Sign because the amount is small","feedback":"Small loans can still carry harmful conditions."},{"text":"Assume informal means interest-free","feedback":"Informal arrangements can carry charges."},{"text":"Pause until the obligations are clear and compare alternatives","feedback":"Unknown obligations prevent an informed affordability decision."}],"correct":2,"explanation":"Unknown obligations prevent an informed affordability decision."}],"summaryTitle":"Bring the ideas together","takeaways":["Clarify gift versus loan.","Know amount, timing and conditions.","Do not accept unclear obligations."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
