if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-4-2","moduleId":"module-4","title":"Interest, Fees and Repayment","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 5: Equity or debt financing","concept":"Calculate and compare total costs of fictional credit offers."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for interest, fees and repayment"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Calculate and compare total costs of fictional credit offers.","outcomes":["Calculate and compare total costs of fictional credit offers."],"situation":{"title":"Interest, Fees and Repayment in student life","body":"Two fictional offers each provide Sampa K500 for one month. Offer A requires K550 repayment and a separate K20 fee. Offer B requires K560 with no other charge. These are invented teaching terms, not local product rates. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Interest is a charge for borrowing. Fees may be charged in addition and may be deducted before money is received. Compare the amount actually received, every payment required, and the payment dates. Total borrowing cost is all required payments minus funds received. A lower headline rate does not guarantee lower total cost. A repayment schedule shows when each instalment is due; cost and timing both matter.","takeaway":"Include every required payment.","definitions":[{"term":"Interest","meaning":"A borrowing charge related to the loan terms.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Total borrowing cost","meaning":"All required payments minus the amount actually received.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Offer A: K550 + K20 = K570 total payments; cost K570 − K500 = K70.","Offer B: K560 total payments; cost K60.","For the same received amount and one-month term, B costs K10 less. Neither is automatically affordable."],"showBudgetTable":false},"practice":{"kind":"numeric","prompt":"Calculate Offer A’s total borrowing cost","context":"Sampa receives K500. Offer A requires K550 repayment plus a separate K20 fee. Offer B costs K60 beyond its K500 principal. Enter A’s cost, then compare.","correct":70,"explanation":"K550 + K20 − K500 = K70. Offer B costs K60, so B is K10 cheaper for the same received amount and term. Check affordability and dates separately.","unit":"K","hint":"Write down the known amounts, then choose the operations. Include all stated costs.","consequence":"K550 + K20 − K500 = K70. Offer B costs K60, so B is K10 cheaper for the same received amount and term. Check affordability and dates separately.","feedback":{"correctTitle":"The calculation is consistent","incorrectTitle":"Recheck the amounts","correct":"K550 + K20 − K500 = K70. Offer B costs K60, so B is K10 cheaper for the same received amount and term. Check affordability and dates separately.","low":"Your answer is below the required amount. K550 + K20 − K500 = K70. Offer B costs K60, so B is K10 cheaper for the same received amount and term. Check affordability and dates separately.","high":"Your answer is above the required amount. K550 + K20 − K500 = K70. Offer B costs K60, so B is K10 cheaper for the same received amount and term. Check affordability and dates separately."}},"checkpoint":[{"id":"lesson-4-2-q1","prompt":"Why compare the amount actually received?","options":[{"text":"Upfront deductions can reduce usable funds","feedback":"Repaying a quoted principal after receiving less increases effective cost."},{"text":"All fees are refunded automatically","feedback":"Refunds cannot be assumed."},{"text":"It replaces checking payment dates","feedback":"Dates still determine whether repayments can be met."}],"correct":0,"explanation":"Repaying a quoted principal after receiving less increases effective cost."},{"id":"lesson-4-2-q2","prompt":"Receive K400; repay K450 and a separate K10 fee. What is the borrowing cost?","options":[{"text":"K50","feedback":"That excludes the fee."},{"text":"K460","feedback":"That is total payments, including principal."},{"text":"K60","feedback":"K450 + K10 − K400 = K60."}],"correct":2,"explanation":"K450 + K10 − K400 = K60."},{"id":"lesson-4-2-q3","prompt":"A cheaper loan is due before income arrives. What else must be checked?","options":[{"text":"Nothing if it is cheaper","feedback":"Affordability is separate from relative price."},{"text":"Cash-flow timing and repayment capacity","feedback":"A low cost does not ensure money is available on the due date."},{"text":"Only the lender’s logo","feedback":"Branding cannot resolve a timing shortfall."}],"correct":1,"explanation":"A low cost does not ensure money is available on the due date."}],"summaryTitle":"Bring the ideas together","takeaways":["Include every required payment.","Compare like amounts and periods.","Cheaper does not always mean affordable."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
