if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-4-3","moduleId":"module-4","title":"Borrowing Affordability","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 5: Equity or debt financing","concept":"Assess repayment against essential obligations and income timing."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for borrowing affordability"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Assess repayment against essential obligations and income timing.","outcomes":["Assess repayment against essential obligations and income timing."],"situation":{"title":"Borrowing Affordability in student life","body":"A student trader in Kasama expects K600 from sales next month. K450 will be needed for stock and living costs. A phone loan requires K200 in two weeks, before the expected sales income arrives. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Repayment capacity is the money that can realistically cover debt after essential costs and existing obligations. Sales are not all disposable income; stock costs matter. Check both the amount and the due date. Expected income may be lower or later than planned, so test a less favourable case. Borrowing for a useful item can still be unaffordable. Consider postponing, repairing, sharing where practical, or seeking assistance before accepting a repayment you cannot support.","takeaway":"Use funds after essential costs.","definitions":[{"term":"Repayment capacity","meaning":"Funds available for repayment after essential commitments.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Timing mismatch","meaning":"A payment is due before funds become available.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Even if K600 arrives, K600 − K450 = K150 remains.","K200 repayment exceeds that amount by K50.","The due date also comes two weeks before expected funds. Both the amount and timing are problems."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What is the affordability conclusion?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Use funds after essential costs.","consequence":"The due date also comes two weeks before expected funds. Both the amount and timing are problems.","options":[{"text":"There is a K50 amount gap and a timing mismatch","feedback":"Expected surplus is only K150 and arrives after the due date."},{"text":"K600 sales guarantees the K200 payment","feedback":"Sales have costs and have not yet arrived."},{"text":"The phone’s usefulness makes repayment affordable","feedback":"Purpose matters, but it does not create repayment funds."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"Expected surplus is only K150 and arrives after the due date.","low":"Sales have costs and have not yet arrived.","high":"Purpose matters, but it does not create repayment funds."}},"checkpoint":[{"id":"lesson-4-3-q1","prompt":"What should be deducted before estimating repayment capacity?","options":[{"text":"Nothing from gross sales","feedback":"Sales may need to cover stock and living costs."},{"text":"Only entertainment expenses","feedback":"Essential costs are particularly important."},{"text":"Essential costs and existing commitments","feedback":"Those funds are already needed for other obligations."}],"correct":2,"explanation":"Those funds are already needed for other obligations."},{"id":"lesson-4-3-q2","prompt":"K700 confirmed income minus K540 essentials leaves how much before debt?","options":[{"text":"K1,240","feedback":"Adding costs overstates funds."},{"text":"K160","feedback":"K700 − K540 = K160."},{"text":"K540","feedback":"That is committed to essentials."}],"correct":1,"explanation":"K700 − K540 = K160."},{"id":"lesson-4-3-q3","prompt":"Income is uncertain. Which check is useful?","options":[{"text":"Test a later or smaller payment before agreeing to borrow","feedback":"A downside scenario reveals how sensitive repayment is."},{"text":"Use only the most optimistic estimate","feedback":"That hides repayment risk."},{"text":"Ignore existing loans","feedback":"Those obligations also use repayment capacity."}],"correct":0,"explanation":"A downside scenario reveals how sensitive repayment is."}],"summaryTitle":"Bring the ideas together","takeaways":["Use funds after essential costs.","Check dates as well as totals.","Test delays and lower income."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-4-3',title='Borrowing Affordability',summary='Assess repayment against essential obligations and income timing.',structured_content='{"id":"lesson-4-3","moduleId":"module-4","title":"Borrowing Affordability","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 5: Equity or debt financing","concept":"Assess repayment against essential obligations and income timing."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for borrowing affordability"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Assess repayment against essential obligations and income timing.","outcomes":["Assess repayment against essential obligations and income timing."],"situation":{"title":"Borrowing Affordability in student life","body":"A student trader in Kasama expects K600 from sales next month. K450 will be needed for stock and living costs. A phone loan requires K200 in two weeks, before the expected sales income arrives. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Repayment capacity is the money that can realistically cover debt after essential costs and existing obligations. Sales are not all disposable income; stock costs matter. Check both the amount and the due date. Expected income may be lower or later than planned, so test a less favourable case. Borrowing for a useful item can still be unaffordable. Consider postponing, repairing, sharing where practical, or seeking assistance before accepting a repayment you cannot support.","takeaway":"Use funds after essential costs.","definitions":[{"term":"Repayment capacity","meaning":"Funds available for repayment after essential commitments.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Timing mismatch","meaning":"A payment is due before funds become available.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Even if K600 arrives, K600 − K450 = K150 remains.","K200 repayment exceeds that amount by K50.","The due date also comes two weeks before expected funds. Both the amount and timing are problems."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What is the affordability conclusion?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Use funds after essential costs.","consequence":"The due date also comes two weeks before expected funds. Both the amount and timing are problems.","options":[{"text":"There is a K50 amount gap and a timing mismatch","feedback":"Expected surplus is only K150 and arrives after the due date."},{"text":"K600 sales guarantees the K200 payment","feedback":"Sales have costs and have not yet arrived."},{"text":"The phone’s usefulness makes repayment affordable","feedback":"Purpose matters, but it does not create repayment funds."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"Expected surplus is only K150 and arrives after the due date.","low":"Sales have costs and have not yet arrived.","high":"Purpose matters, but it does not create repayment funds."}},"checkpoint":[{"id":"lesson-4-3-q1","prompt":"What should be deducted before estimating repayment capacity?","options":[{"text":"Nothing from gross sales","feedback":"Sales may need to cover stock and living costs."},{"text":"Only entertainment expenses","feedback":"Essential costs are particularly important."},{"text":"Essential costs and existing commitments","feedback":"Those funds are already needed for other obligations."}],"correct":2,"explanation":"Those funds are already needed for other obligations."},{"id":"lesson-4-3-q2","prompt":"K700 confirmed income minus K540 essentials leaves how much before debt?","options":[{"text":"K1,240","feedback":"Adding costs overstates funds."},{"text":"K160","feedback":"K700 − K540 = K160."},{"text":"K540","feedback":"That is committed to essentials."}],"correct":1,"explanation":"K700 − K540 = K160."},{"id":"lesson-4-3-q3","prompt":"Income is uncertain. Which check is useful?","options":[{"text":"Test a later or smaller payment before agreeing to borrow","feedback":"A downside scenario reveals how sensitive repayment is."},{"text":"Use only the most optimistic estimate","feedback":"That hides repayment risk."},{"text":"Ignore existing loans","feedback":"Those obligations also use repayment capacity."}],"correct":0,"explanation":"A downside scenario reveals how sensitive repayment is."}],"summaryTitle":"Bring the ideas together","takeaways":["Use funds after essential costs.","Check dates as well as totals.","Test delays and lower income."]}'::jsonb,content='Repayment capacity is the money that can realistically cover debt after essential costs and existing obligations. Sales are not all disposable income; stock costs matter. Check both the amount and the due date. Expected income may be lower or later than planned, so test a less favourable case. Borrowing for a useful item can still be unaffordable. Consider postponing, repairing, sharing where practical, or seeking assistance before accepting a repayment you cannot support.',revision=1,estimated_minutes=10,is_published=true where id=lid;
