if lid is null then lid:='28336278-9452-4eec-af2c-e4b65a19333d'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Managing Debt Responsibly','',4); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-4-4","moduleId":"module-4","title":"Managing Debt Responsibly","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 8: Financial negotiations","concept":"Organise debts and evaluate communication and repayment choices."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for managing debt responsibly"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 15–17: Talking About Money; Resolving Conflicts About Money","concept":"Organise debts and evaluate communication and repayment choices. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Organise debts and evaluate communication and repayment choices.","outcomes":["Organise debts and evaluate communication and repayment choices."],"situation":{"title":"Managing Debt Responsibly in student life","body":"Agness owes K200 to a friend and K300 to another lender. She can pay K150 after essentials this month. A third lender offers K500 to settle both, but would require K650 next month. She has no evidence that next month’s capacity will improve. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"List each outstanding balance, due date, required payment, charge and contact. Communicate early when a payment may be missed and ask about feasible arrangements; acceptance is not guaranteed. Taking new debt to settle old debt without improving repayment capacity can create debt cycling. Credit records may be relevant to formal lending decisions; ask a regulated provider how your information is used and how to question errors. Do not assume all informal borrowing is reported or that any particular outcome is guaranteed.","takeaway":"List balances and due dates.","definitions":[{"term":"Outstanding balance","meaning":"The amount still owed.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Debt cycling","meaning":"Repeatedly using new borrowing to service old debt without resolving repayment capacity.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Existing debt totals K200 + K300 = K500.","Replacing it with the new offer would require K650, adding K150 to the future obligation.","K150 capacity cannot settle K500 now. Record the gap and discuss feasible payments with each creditor before committing the same funds twice."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which first response addresses the actual problem?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"List balances and due dates.","consequence":"K150 capacity cannot settle K500 now. Record the gap and discuss feasible payments with each creditor before committing the same funds twice.","options":[{"text":"List terms and discuss realistic payments before taking more debt","feedback":"This makes the shortfall explicit and avoids assuming new debt solves capacity."},{"text":"Borrow K500 because the old balances disappear","feedback":"They are replaced by a larger K650 obligation."},{"text":"Promise both creditors the same K150 in full","feedback":"That promises K300 using only K150."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This makes the shortfall explicit and avoids assuming new debt solves capacity.","low":"They are replaced by a larger K650 obligation.","high":"That promises K300 using only K150."}},"checkpoint":[{"id":"lesson-4-4-q1","prompt":"What is an outstanding balance?","options":[{"text":"Only the original interest rate","feedback":"A rate is different from an amount owed."},{"text":"The amount still owed","feedback":"It reflects unpaid debt."},{"text":"All income ever earned","feedback":"Income is not a debt balance."}],"correct":1,"explanation":"It reflects unpaid debt."},{"id":"lesson-4-4-q2","prompt":"A K420 debt falls by a K120 principal payment, with no new charges. What remains?","options":[{"text":"K300","feedback":"K420 − K120 = K300."},{"text":"K540","feedback":"A repayment reduces this balance."},{"text":"K120","feedback":"That is the amount paid, not what remains."}],"correct":0,"explanation":"K420 − K120 = K300."},{"id":"lesson-4-4-q3","prompt":"A payment may be missed. Which action is useful?","options":[{"text":"Ignore every message","feedback":"Avoidance prevents clarifying options."},{"text":"Assume another loan always improves matters","feedback":"New debt can increase total obligations."},{"text":"Contact the creditor early and keep records of any agreement","feedback":"Early communication supports realistic discussion, though changes are not guaranteed."}],"correct":2,"explanation":"Early communication supports realistic discussion, though changes are not guaranteed."}],"summaryTitle":"Bring the ideas together","takeaways":["List balances and due dates.","Communicate before problems grow.","Check whether new borrowing worsens the obligation."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-4-4',title='Managing Debt Responsibly',summary='Organise debts and evaluate communication and repayment choices.',structured_content='{"id":"lesson-4-4","moduleId":"module-4","title":"Managing Debt Responsibly","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","ilo","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"ilo","section":"Session 8: Financial negotiations","concept":"Organise debts and evaluate communication and repayment choices."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for managing debt responsibly"},{"source":"finscope","section":"9.3 Credit Services; 6.1.4.4 Kaloba","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 15–17: Talking About Money; Resolving Conflicts About Money","concept":"Organise debts and evaluate communication and repayment choices. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Organise debts and evaluate communication and repayment choices.","outcomes":["Organise debts and evaluate communication and repayment choices."],"situation":{"title":"Managing Debt Responsibly in student life","body":"Agness owes K200 to a friend and K300 to another lender. She can pay K150 after essentials this month. A third lender offers K500 to settle both, but would require K650 next month. She has no evidence that next month’s capacity will improve. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"List each outstanding balance, due date, required payment, charge and contact. Communicate early when a payment may be missed and ask about feasible arrangements; acceptance is not guaranteed. Taking new debt to settle old debt without improving repayment capacity can create debt cycling. Credit records may be relevant to formal lending decisions; ask a regulated provider how your information is used and how to question errors. Do not assume all informal borrowing is reported or that any particular outcome is guaranteed.","takeaway":"List balances and due dates.","definitions":[{"term":"Outstanding balance","meaning":"The amount still owed.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Debt cycling","meaning":"Repeatedly using new borrowing to service old debt without resolving repayment capacity.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Existing debt totals K200 + K300 = K500.","Replacing it with the new offer would require K650, adding K150 to the future obligation.","K150 capacity cannot settle K500 now. Record the gap and discuss feasible payments with each creditor before committing the same funds twice."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which first response addresses the actual problem?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"List balances and due dates.","consequence":"K150 capacity cannot settle K500 now. Record the gap and discuss feasible payments with each creditor before committing the same funds twice.","options":[{"text":"List terms and discuss realistic payments before taking more debt","feedback":"This makes the shortfall explicit and avoids assuming new debt solves capacity."},{"text":"Borrow K500 because the old balances disappear","feedback":"They are replaced by a larger K650 obligation."},{"text":"Promise both creditors the same K150 in full","feedback":"That promises K300 using only K150."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This makes the shortfall explicit and avoids assuming new debt solves capacity.","low":"They are replaced by a larger K650 obligation.","high":"That promises K300 using only K150."}},"checkpoint":[{"id":"lesson-4-4-q1","prompt":"What is an outstanding balance?","options":[{"text":"Only the original interest rate","feedback":"A rate is different from an amount owed."},{"text":"The amount still owed","feedback":"It reflects unpaid debt."},{"text":"All income ever earned","feedback":"Income is not a debt balance."}],"correct":1,"explanation":"It reflects unpaid debt."},{"id":"lesson-4-4-q2","prompt":"A K420 debt falls by a K120 principal payment, with no new charges. What remains?","options":[{"text":"K300","feedback":"K420 − K120 = K300."},{"text":"K540","feedback":"A repayment reduces this balance."},{"text":"K120","feedback":"That is the amount paid, not what remains."}],"correct":0,"explanation":"K420 − K120 = K300."},{"id":"lesson-4-4-q3","prompt":"A payment may be missed. Which action is useful?","options":[{"text":"Ignore every message","feedback":"Avoidance prevents clarifying options."},{"text":"Assume another loan always improves matters","feedback":"New debt can increase total obligations."},{"text":"Contact the creditor early and keep records of any agreement","feedback":"Early communication supports realistic discussion, though changes are not guaranteed."}],"correct":2,"explanation":"Early communication supports realistic discussion, though changes are not guaranteed."}],"summaryTitle":"Bring the ideas together","takeaways":["List balances and due dates.","Communicate before problems grow.","Check whether new borrowing worsens the obligation."]}'::jsonb,content='List each outstanding balance, due date, required payment, charge and contact. Communicate early when a payment may be missed and ask about feasible arrangements; acceptance is not guaranteed. Taking new debt to settle old debt without improving repayment capacity can create debt cycling. Credit records may be relevant to formal lending decisions; ask a regulated provider how your information is used and how to question errors. Do not assume all informal borrowing is reported or that any particular outcome is guaranteed.',revision=1,estimated_minutes=10,is_published=true where id=lid;
