if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-5-1","moduleId":"module-5","title":"Mobile Money and Digital Payments","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Verify a payment destination and confirm a transaction safely."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for mobile money and digital payments"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Verify a payment destination and confirm a transaction safely.","outcomes":["Verify a payment destination and confirm a transaction safely."],"situation":{"title":"Mobile Money and Digital Payments in student life","body":"Thandi receives a message naming a mobile-money number for a university fee. The university portal lists different instructions. A caller says the portal is wrong and urges her to pay immediately. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Mobile money and bank accounts can support digital payments, but their terms, access and protections are not identical. A payment transfers value to a recipient; verify the recipient identity, amount, reference and applicable charge before authorising it. Use a university or provider contact obtained independently, not a number supplied in the suspicious message. After payment, check your own account history and retain the reference. A screenshot alone does not establish that funds arrived.","takeaway":"Verify payment instructions independently.","definitions":[{"term":"Recipient","meaning":"The person or organisation receiving payment.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Payment reference","meaning":"An identifier used to match a payment to its purpose.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Pause because the instructions conflict.","Contact the university finance office through independently obtained official details and verify the account and required reference.","After a verified payment, retain the transaction ID and check account history. Do not send a second payment solely because a caller requests it."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Thandi do before paying?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Verify payment instructions independently.","consequence":"After a verified payment, retain the transaction ID and check account history. Do not send a second payment solely because a caller requests it.","options":[{"text":"Verify instructions with the university through an independent official channel","feedback":"This avoids relying on the person requesting the payment."},{"text":"Pay the caller’s number because they sound confident","feedback":"Confidence is not verification."},{"text":"Send her PIN so the caller can check the account","feedback":"A PIN authorises access and must remain private."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This avoids relying on the person requesting the payment.","low":"Confidence is not verification.","high":"A PIN authorises access and must remain private."}},"checkpoint":[{"id":"lesson-5-1-q1","prompt":"What should be checked before authorising a payment?","options":[{"text":"Recipient, amount, reference and charges","feedback":"These determine where money goes and the total cost."},{"text":"Only the caller’s display name","feedback":"A name can be imitated."},{"text":"Only the phone battery level","feedback":"That does not verify the transaction."}],"correct":0,"explanation":"These determine where money goes and the total cost."},{"id":"lesson-5-1-q2","prompt":"A fictional payment is K120 with K3 fee. How much leaves the account?","options":[{"text":"K120","feedback":"That omits the fee."},{"text":"K117","feedback":"The fee is added, not returned."},{"text":"K123","feedback":"K120 + K3 = K123."}],"correct":2,"explanation":"K120 + K3 = K123."},{"id":"lesson-5-1-q3","prompt":"A screenshot says payment succeeded but your account shows no receipt. What next?","options":[{"text":"Ask the sender for their OTP","feedback":"Other people’s credentials should not be requested or shared."},{"text":"Check through your own provider’s official channel","feedback":"Independent account verification is stronger than a screenshot."},{"text":"Release goods immediately","feedback":"The screenshot may be inaccurate or forged."}],"correct":1,"explanation":"Independent account verification is stronger than a screenshot."}],"summaryTitle":"Bring the ideas together","takeaways":["Verify payment instructions independently.","Check recipient and total cost before authorising.","Keep your own transaction record."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-5-1',title='Mobile Money and Digital Payments',summary='Verify a payment destination and confirm a transaction safely.',structured_content='{"id":"lesson-5-1","moduleId":"module-5","title":"Mobile Money and Digital Payments","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Verify a payment destination and confirm a transaction safely."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for mobile money and digital payments"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Verify a payment destination and confirm a transaction safely.","outcomes":["Verify a payment destination and confirm a transaction safely."],"situation":{"title":"Mobile Money and Digital Payments in student life","body":"Thandi receives a message naming a mobile-money number for a university fee. The university portal lists different instructions. A caller says the portal is wrong and urges her to pay immediately. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Mobile money and bank accounts can support digital payments, but their terms, access and protections are not identical. A payment transfers value to a recipient; verify the recipient identity, amount, reference and applicable charge before authorising it. Use a university or provider contact obtained independently, not a number supplied in the suspicious message. After payment, check your own account history and retain the reference. A screenshot alone does not establish that funds arrived.","takeaway":"Verify payment instructions independently.","definitions":[{"term":"Recipient","meaning":"The person or organisation receiving payment.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Payment reference","meaning":"An identifier used to match a payment to its purpose.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Pause because the instructions conflict.","Contact the university finance office through independently obtained official details and verify the account and required reference.","After a verified payment, retain the transaction ID and check account history. Do not send a second payment solely because a caller requests it."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Thandi do before paying?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Verify payment instructions independently.","consequence":"After a verified payment, retain the transaction ID and check account history. Do not send a second payment solely because a caller requests it.","options":[{"text":"Verify instructions with the university through an independent official channel","feedback":"This avoids relying on the person requesting the payment."},{"text":"Pay the caller’s number because they sound confident","feedback":"Confidence is not verification."},{"text":"Send her PIN so the caller can check the account","feedback":"A PIN authorises access and must remain private."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This avoids relying on the person requesting the payment.","low":"Confidence is not verification.","high":"A PIN authorises access and must remain private."}},"checkpoint":[{"id":"lesson-5-1-q1","prompt":"What should be checked before authorising a payment?","options":[{"text":"Recipient, amount, reference and charges","feedback":"These determine where money goes and the total cost."},{"text":"Only the caller’s display name","feedback":"A name can be imitated."},{"text":"Only the phone battery level","feedback":"That does not verify the transaction."}],"correct":0,"explanation":"These determine where money goes and the total cost."},{"id":"lesson-5-1-q2","prompt":"A fictional payment is K120 with K3 fee. How much leaves the account?","options":[{"text":"K120","feedback":"That omits the fee."},{"text":"K117","feedback":"The fee is added, not returned."},{"text":"K123","feedback":"K120 + K3 = K123."}],"correct":2,"explanation":"K120 + K3 = K123."},{"id":"lesson-5-1-q3","prompt":"A screenshot says payment succeeded but your account shows no receipt. What next?","options":[{"text":"Ask the sender for their OTP","feedback":"Other people’s credentials should not be requested or shared."},{"text":"Check through your own provider’s official channel","feedback":"Independent account verification is stronger than a screenshot."},{"text":"Release goods immediately","feedback":"The screenshot may be inaccurate or forged."}],"correct":1,"explanation":"Independent account verification is stronger than a screenshot."}],"summaryTitle":"Bring the ideas together","takeaways":["Verify payment instructions independently.","Check recipient and total cost before authorising.","Keep your own transaction record."]}'::jsonb,content='Mobile money and bank accounts can support digital payments, but their terms, access and protections are not identical. A payment transfers value to a recipient; verify the recipient identity, amount, reference and applicable charge before authorising it. Use a university or provider contact obtained independently, not a number supplied in the suspicious message. After payment, check your own account history and retain the reference. A screenshot alone does not establish that funds arrived.',revision=1,estimated_minutes=10,is_published=true where id=lid;
