if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-5-2","moduleId":"module-5","title":"Transaction Fees and Records","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Reconcile transfers and charges across different money holdings."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for transaction fees and records"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Reconcile transfers and charges across different money holdings.","outcomes":["Reconcile transfers and charges across different money holdings."],"situation":{"title":"Transaction Fees and Records in student life","body":"David has K600 across his own bank and wallet balances. He transfers K150 between them, pays a fictional K4 transfer charge and buys K90 materials. Later he sees the transfer in both statements. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A transfer can appear as an outgoing item in one account and an incoming item in another. In a combined personal record these are one movement of existing funds, not new income and consumption. Fees reduce total holdings and should be recorded separately. Receipts and references help match entries across statements. Reconciliation should use the same date range and include pending items separately from confirmed transactions.","takeaway":"Match both sides of own transfers.","definitions":[{"term":"Receipt","meaning":"Evidence containing transaction details.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Reconciled balance","meaning":"A balance checked against recorded confirmed movements.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Own-account transfer: combined funds stay K600 before charges.","K4 charge and K90 purchase reduce combined funds by K94.","Combined balance is K506. Match the K150 outgoing and incoming references without adding K150 income."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"How should David reconcile the transfer?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Match both sides of own transfers.","consequence":"Combined balance is K506. Match the K150 outgoing and incoming references without adding K150 income.","options":[{"text":"Match both sides as one transfer and record K4 fee separately","feedback":"The transfer changes location, while the fee reduces total money."},{"text":"Record the incoming K150 as earnings","feedback":"This overstates new income."},{"text":"Ignore the K4 because it is small","feedback":"Even a small fee affects the balance."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The transfer changes location, while the fee reduces total money.","low":"This overstates new income.","high":"Even a small fee affects the balance."}},"checkpoint":[{"id":"lesson-5-2-q1","prompt":"What helps match a transaction across records?","options":[{"text":"The colour of the phone case","feedback":"That is unrelated to the transaction."},{"text":"A guessed category alone","feedback":"A category does not uniquely identify a payment."},{"text":"Date, amount and reference","feedback":"Together they support identification and reconciliation."}],"correct":2,"explanation":"Together they support identification and reconciliation."},{"id":"lesson-5-2-q2","prompt":"K800 combined funds, K200 own transfer, K6 fee and K140 purchase leave what?","options":[{"text":"K660","feedback":"That omits the fee."},{"text":"K654","feedback":"K800 − K6 − K140 = K654."},{"text":"K454","feedback":"That subtracts the transfer as spending."}],"correct":1,"explanation":"K800 − K6 − K140 = K654."},{"id":"lesson-5-2-q3","prompt":"A charge differs from what you expected. What should you do?","options":[{"text":"Check the disclosed terms and ask the provider using the transaction details","feedback":"Records support a specific enquiry without assuming a cause."},{"text":"Delete the charge from your record","feedback":"That does not restore the money."},{"text":"Assume all providers charge the same","feedback":"Charges and conditions vary."}],"correct":0,"explanation":"Records support a specific enquiry without assuming a cause."}],"summaryTitle":"Bring the ideas together","takeaways":["Match both sides of own transfers.","Record charges as expenses.","Use references and dates to investigate differences."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-5-2',title='Transaction Fees and Records',summary='Reconcile transfers and charges across different money holdings.',structured_content='{"id":"lesson-5-2","moduleId":"module-5","title":"Transaction Fees and Records","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Reconcile transfers and charges across different money holdings."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for transaction fees and records"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Reconcile transfers and charges across different money holdings.","outcomes":["Reconcile transfers and charges across different money holdings."],"situation":{"title":"Transaction Fees and Records in student life","body":"David has K600 across his own bank and wallet balances. He transfers K150 between them, pays a fictional K4 transfer charge and buys K90 materials. Later he sees the transfer in both statements. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"A transfer can appear as an outgoing item in one account and an incoming item in another. In a combined personal r