nstraint","incorrectTitle":"Consider the consequence","correct":"The transfer changes location, while the fee reduces total money.","low":"This overstates new income.","high":"Even a small fee affects the balance."}},"checkpoint":[{"id":"lesson-5-2-q1","prompt":"What helps match a transaction across records?","options":[{"text":"The colour of the phone case","feedback":"That is unrelated to the transaction."},{"text":"A guessed category alone","feedback":"A category does not uniquely identify a payment."},{"text":"Date, amount and reference","feedback":"Together they support identification and reconciliation."}],"correct":2,"explanation":"Together they support identification and reconciliation."},{"id":"lesson-5-2-q2","prompt":"K800 combined funds, K200 own transfer, K6 fee and K140 purchase leave what?","options":[{"text":"K660","feedback":"That omits the fee."},{"text":"K654","feedback":"K800 − K6 − K140 = K654."},{"text":"K454","feedback":"That subtracts the transfer as spending."}],"correct":1,"explanation":"K800 − K6 − K140 = K654."},{"id":"lesson-5-2-q3","prompt":"A charge differs from what you expected. What should you do?","options":[{"text":"Check the disclosed terms and ask the provider using the transaction details","feedback":"Records support a specific enquiry without assuming a cause."},{"text":"Delete the charge from your record","feedback":"That does not restore the money."},{"text":"Assume all providers charge the same","feedback":"Charges and conditions vary."}],"correct":0,"explanation":"Records support a specific enquiry without assuming a cause."}],"summaryTitle":"Bring the ideas together","takeaways":["Match both sides of own transfers.","Record charges as expenses.","Use references and dates to investigate differences."]}'::jsonb,content='A transfer can appear as an outgoing item in one account and an incoming item in another. In a combined personal record these are one movement of existing funds, not new income and consumption. Fees reduce total holdings and should be recorded separately. Receipts and references help match entries across statements. Reconciliation should use the same date range and include pending items separately from confirmed transactions.',revision=1,estimated_minutes=10,is_published=true where id=lid;
