if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-5-3","moduleId":"module-5","title":"Scams and Digital Security","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Recognise social engineering and choose a safe verification response."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for scams and digital security"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Recognise social engineering and choose a safe verification response.","outcomes":["Recognise social engineering and choose a safe verification response."],"situation":{"title":"Scams and Digital Security in student life","body":"A caller tells Bwalya that K250 was sent to her by mistake. They send a convincing screenshot, demand an immediate refund and ask for an OTP to “reverse the transfer”. Bwalya has not checked her own account. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Social engineering pressures people into revealing information or moving money. Phishing uses deceptive messages or sites to obtain credentials. PINs and one-time passwords authorise access or actions and should not be shared with callers. Screenshots and sender names can be falsified. Verify through your own app or independently obtained provider contact. If a genuine mistaken transfer appears, use the provider’s official resolution process rather than improvising a payment to a stranger. Report suspected compromise promptly.","takeaway":"Keep PINs and OTPs private.","definitions":[{"term":"Phishing","meaning":"Deceptive communication designed to obtain sensitive information or access.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"OTP","meaning":"A one-time password used to authorise or verify an action.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Do not disclose the OTP or follow the caller’s link.","Check your own transaction history through the app you normally use.","Contact the provider independently about any unexpected receipt. Keep messages and references for the report."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which response is safest?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Keep PINs and OTPs private.","consequence":"Contact the provider independently about any unexpected receipt. Keep messages and references for the report.","options":[{"text":"End the pressured conversation and verify with the provider independently","feedback":"This protects credentials while checking whether any real transaction occurred."},{"text":"Read out the OTP to prove cooperation","feedback":"The code may authorise an unwanted action."},{"text":"Refund the screenshot amount immediately","feedback":"A screenshot does not prove receipt and the requested destination may differ."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This protects credentials while checking whether any real transaction occurred.","low":"The code may authorise an unwanted action.","high":"A screenshot does not prove receipt and the requested destination may differ."}},"checkpoint":[{"id":"lesson-5-3-q1","prompt":"Which is a warning sign?","options":[{"text":"Keeping a receipt privately","feedback":"Private records can help resolve issues."},{"text":"Pressure to reveal an OTP immediately","feedback":"Urgency and credential requests are common manipulation tactics."},{"text":"Checking your own statement","feedback":"That is an independent verification step."}],"correct":1,"explanation":"Urgency and credential requests are common manipulation tactics."},{"id":"lesson-5-3-q2","prompt":"You disclosed a PIN to a suspicious caller. What should you do?","options":[{"text":"Use official provider channels promptly to secure the account and report it","feedback":"Acting quickly may limit further access; follow verified provider instructions."},{"text":"Wait until the caller confirms they are finished","feedback":"That prolongs exposure."},{"text":"Post the PIN publicly to warn others","feedback":"That exposes it to more people."}],"correct":0,"explanation":"Acting quickly may limit further access; follow verified provider instructions."},{"id":"lesson-5-3-q3","prompt":"Why avoid a support number inside a suspicious message?","options":[{"text":"All support services are fraudulent","feedback":"Legitimate support exists; verify the channel."},{"text":"A local number guarantees safety","feedback":"A local number alone does not establish identity."},{"text":"It may lead back to the attacker","feedback":"Independent contact details avoid trusting the same unverified source."}],"correct":2,"explanation":"Independent contact details avoid trusting the same unverified source."}],"summaryTitle":"Bring the ideas together","takeaways":["Keep PINs and OTPs private.","Verify through independent channels.","Preserve evidence and report suspected compromise."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
