if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-5-4","moduleId":"module-5","title":"Consumer Rights and Complaints","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","boz"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Prepare a transaction enquiry and identify a provider-first complaint route."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for consumer rights and complaints"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"boz","section":"19.2.1","concept":"Provider-first complaints principle; no asserted deadline or refund entitlement"}],"introduction":"Prepare a transaction enquiry and identify a provider-first complaint route.","outcomes":["Prepare a transaction enquiry and identify a provider-first complaint route."],"situation":{"title":"Consumer Rights and Complaints in student life","body":"Joseph sends K180 for supplies. His account shows a debit, but the recipient reports no receipt. He has the transaction ID and date. He wants the issue investigated without sending another payment blindly. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Clear information about terms and charges helps consumers make informed decisions. When a payment is disputed, collect the date, amount, recipient details, reference and your own account record. Contact the provider through an independently verified official channel and request a case reference. Keep a timeline and responses. For a Bank of Zambia-regulated provider, the published complaints directives require first raising the complaint with the provider; consult the Bank’s current official guidance for any escalation. Different financial sectors have different regulators. No refund or resolution time is promised here.","takeaway":"Keep clear transaction evidence.","definitions":[{"term":"Complaint reference","meaning":"An identifier used to follow an enquiry or complaint.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Disclosure","meaning":"Information provided about terms, charges and conditions.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Compile: K180, date and time, transaction ID, intended recipient and debit record.","Ask the provider to trace the payment and explain its status; retain the case number.","If unresolved, use the relevant regulator’s current official guidance and include the provider correspondence. Never send a PIN or OTP as complaint evidence."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Joseph do first?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Keep clear transaction evidence.","consequence":"If unresolved, use the relevant regulator’s current official guidance and include the provider correspondence. Never send a PIN or OTP as complaint evidence.","options":[{"text":"Ask the provider to investigate using his transaction details","feedback":"This supports tracing the payment and creates a record for follow-up."},{"text":"Send another K180 without checking","feedback":"That risks paying twice."},{"text":"Publish his PIN with the complaint","feedback":"Credentials are not needed as public evidence and must be protected."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This supports tracing the payment and creates a record for follow-up.","low":"That risks paying twice.","high":"Credentials are not needed as public evidence and must be protected."}},"checkpoint":[{"id":"lesson-5-4-q1","prompt":"Which record is useful in a payment complaint?","options":[{"text":"Transaction reference and amount","feedback":"They help identify the disputed payment."},{"text":"The account PIN","feedback":"The PIN should remain private."},{"text":"A guessed transaction date","feedback":"Use the actual date from records if available."}],"correct":0,"explanation":"They help identify the disputed payment."},{"id":"lesson-5-4-q2","prompt":"Two K180 payments were sent while only one was intended. What should be investigated?","options":[{"text":"Assume one never happened","feedback":"An assumption is not reconciliation."},{"text":"Delete one receipt","feedback":"Evidence should be retained."},{"text":"Whether both debits completed and how the duplicate can be addressed","feedback":"Use records to distinguish completed, pending or reversed items."}],"correct":2,"explanation":"Use records to distinguish completed, pending or reversed items."},{"id":"lesson-5-4-q3","prompt":"A provider complaint remains unresolved. What is the next information to check?","options":[{"text":"A guaranteed immediate refund from every regulator","feedback":"Outcomes and timing cannot be guaranteed."},{"text":"The relevant regulator’s current escalation guidance","feedback":"The correct route depends on the provider and sector; retain the first complaint record."},{"text":"Any refund promise from a social-media stranger","feedback":"Unverified promises can create further risk."}],"correct":1,"explanation":"The correct route depends on the provider and sector; retain the first complaint record."}],"summaryTitle":"Bring the ideas together","takeaways":["Keep clear transaction evidence.","Complain through verified provider channels first.","Check the relevant regulator’s current escalation guidance."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-5-4',title='Consumer Rights and Complaints',summary='Prepare a transaction enquiry and identify a provider-first complaint route.',structured_content='{"id":"lesson-5-4","moduleId":"module-5","title":"Consumer Rights and Complaints","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","boz"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Prepare a transaction enquiry and identify a provider-first complaint route."},{"source":"worldbank","section":"Financial consumer protection","concept":"Zambian context for consumer rights and complaints"},{"source":"finscope","section":"9.1 Money Transfer and Payment Services","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"boz","section":"19.2.1","concept":"Provider-first complaints principle; no asserted deadline or refund entitlement"}],"introduction":"Prepare a transaction enquiry and identify a provider-first complaint route.","outcomes":["Prepare a transaction enquiry and identify a provider-first complaint route."],"situation":{"title":"Consumer Rights and Complaints in student life","body":"Joseph sends K180 for supplies. His account shows a debit, but the recipient reports no receipt. He has the transaction ID and date. He wants the issue investigated without sending another payment blindly. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Clear information about terms and charges helps consumers make informed decisions. When a payment is disputed, collect the date, amount, recipient details, reference and your own account record. Contact the provider through an independently verified official channel and request a case reference. Keep a timeline and responses. For a Bank of Zambia-regulated provider, the published complaints directives require first raising the complaint with the provider; consult the Bank’s current official guidance for any escalation. Different financial sectors have different regulators. No refund or resolution time is promised here.","takeaway":"Keep clear transaction evidence.","definitions":[{"term":"Complaint reference","meaning":"An identifier used to follow an enquiry or complaint.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Disclosure","meaning":"Information provided about terms, charges and conditions.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Compile: K180, date and time, transaction ID, intended recipient and debit record.","Ask the provider to trace the payment and explain its status; retain the case number.","If unresolved, use the relevant regulator’s current official guidance and include the provider correspondence. Never send a PIN or OTP as complaint evidence."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"What should Joseph do first?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Keep clear transaction evidence.","consequence":"If unresolved, use the relevant regulator’s current official guidance and include the provider correspondence. Never send a PIN or OTP as complaint evidence.","options":[{"text":"Ask the provider to investigate using his transaction details","feedback":"This supports tracing the payment and creates a record for follow-up."},{"text":"Send another K180 without checking","feedback":"That risks paying twice."},{"text":"Publish his PIN with the complaint","feedback":"Credentials are not needed as public evidence and must be protected."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"This supports tracing the payment and creates a record for follow-up.","low":"That risks paying twice.","high":"Credentials are not needed as public evidence and must be protected."}},"checkpoint":[{"id":"lesson-5-4-q1","prompt":"Which record is useful in a payment complaint?","options":[{"text":"Transaction reference and amount","feedback":"They help identify the disputed payment."},{"text":"The account PIN","feedback":"The PIN should remain private."},{"text":"A guessed transaction date","feedback":"Use the actual date from records if available."}],"correct":0,"explanation":"They help identify the disputed payment."},{"id":"lesson-5-4-q2","prompt":"Two K180 payments were sent while only one was intended. What should be investigated?","options":[{"text":"Assume one never happened","feedback":"An assumption is not reconciliation."},{"text":"Delete one receipt","feedback":"Evidence should be retained."},{"text":"Whether both debits completed and how the duplicate can be addressed","feedback":"Use records to distinguish completed, pending or reversed items."}],"correct":2,"explanation":"Use records to distinguish completed, pending or reversed items."},{"id":"lesson-5-4-q3","prompt":"A provider complaint remains unresolved. What is the next information to check?","options":[{"text":"A guaranteed immediate refund from every regulator","feedback":"Outcomes and timing cannot be guaranteed."},{"text":"The relevant regulator’s current escalation guidance","feedback":"The correct route depends on the provider and sector; retain the first complaint record."},{"text":"Any refund promise from a social-media stranger","feedback":"Unverified promises can create further risk."}],"correct":1,"explanation":"The correct route depends on the provider and sector; retain the first complaint record."}],"summaryTitle":"Bring the ideas together","takeaways":["Keep clear transaction evidence.","Complain through verified provider channels first.","Check the relevant regulator’s current escalation guidance."]}'::jsonb,content='Clear information about terms and charges helps consumers make informed decisions. When a payment is disputed, collect the date, amount, recipient details, reference and your own account record. Contact the provider through an independently verified official channel and request a case reference. Keep a timeline and responses. For a Bank of Zambia-regulated provider, the published complaints directives require first raising the complaint with the provider; consult the Bank’s current official guidance for any escalation. Different financial sectors have different regulators. No refund or resolution time is promised here.',revision=1,estimated_minutes=10,is_published=true where id=lid;
