if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-6-1","moduleId":"module-6","title":"Planning Beyond This Month","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Build a timeline for future commitments under uncertain employment income."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for planning beyond this month"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 3–4: Choose a Savings Goal; Make a Savings Plan","concept":"Build a timeline for future commitments under uncertain employment income. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Build a timeline for future commitments under uncertain employment income.","outcomes":["Build a timeline for future commitments under uncertain employment income."],"situation":{"title":"Planning Beyond This Month in student life","body":"Final-year student Memory expects to graduate in four months. She estimates K800 for graduation-related travel and documents and has K200 saved. She hopes to find work quickly but has no job offer or start date. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Longer-term planning connects foreseeable commitments to dates and resources. Separate known costs from estimates and confirmed income from hopes. Preparing for work can involve transport, documents and communication costs before wages arrive. Compare a baseline plan with a delayed-income case. Break large commitments into smaller steps and review periodically. Support networks and information about opportunities can be part of a plan; employment is not guaranteed by budgeting.","takeaway":"Map future costs to dates.","definitions":[{"term":"Planning horizon","meaning":"The future period considered in a plan.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Scenario plan","meaning":"A plan that considers more than one possible outcome.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Remaining estimated cost: K800 − K200 = K600.","Over four months the target contribution is K150 monthly if affordable.","A delayed-job case must cover the period without assuming a salary. If K150 is unrealistic, revise costs or timing and explore support."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which plan handles uncertain employment responsibly?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Map future costs to dates.","consequence":"A delayed-job case must cover the period without assuming a salary. If K150 is unrealistic, revise costs or timing and explore support.","options":[{"text":"Plan graduation costs using current resources and test a delayed-job case","feedback":"It avoids treating hoped-for wages as confirmed funds."},{"text":"Commit the first salary before any job offer","feedback":"There is no confirmed amount or date."},{"text":"Ignore future costs because they are not due today","feedback":"Known commitments can be prepared for gradually."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"It avoids treating hoped-for wages as confirmed funds.","low":"There is no confirmed amount or date.","high":"Known commitments can be prepared for gradually."}},"checkpoint":[{"id":"lesson-6-1-q1","prompt":"What makes a future income estimate different from confirmed income?","options":[{"text":"It is always larger","feedback":"An estimate can be higher or lower."},{"text":"It never matters to planning","feedback":"It matters as a scenario, not as money already available."},{"text":"Its amount or arrival is not yet certain","feedback":"Uncertainty affects what commitments it can safely support."}],"correct":2,"explanation":"Uncertainty affects what commitments it can safely support."},{"id":"lesson-6-1-q2","prompt":"K1,000 goal, K400 saved and five months remaining require what monthly contribution?","options":[{"text":"K600","feedback":"That is the total gap."},{"text":"K120","feedback":"(K1,000 − K400) ÷ 5 = K120."},{"text":"K200","feedback":"That ignores existing savings."}],"correct":1,"explanation":"(K1,000 − K400) ÷ 5 = K120."},{"id":"lesson-6-1-q3","prompt":"A job start date is delayed. What should the plan do?","options":[{"text":"Revisit essential costs and the period before first pay","feedback":"The change affects cash-flow timing."},{"text":"Keep spending the expected salary","feedback":"The money has not arrived."},{"text":"Assume every future plan is useless","feedback":"Plans can be revised when circumstances change."}],"correct":0,"explanation":"The change affects cash-flow timing."}],"summaryTitle":"Bring the ideas together","takeaways":["Map future costs to dates.","Separate hopes from confirmed resources.","Prepare a delayed-income scenario."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-6-1',title='Planning Beyond This Month',summary='Build a timeline for future commitments under uncertain employment income.',structured_content='{"id":"lesson-6-1","moduleId":"module-6","title":"Planning Beyond This Month","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","council"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Build a timeline for future commitments under uncertain employment income."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for planning beyond this month"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"council","section":"Sessions 3–4: Choose a Savings Goal; Make a Savings Plan","concept":"Build a timeline for future commitments under uncertain employment income. Original scenario and exercise; no manual activity reproduced."}],"introduction":"Build a timeline for future commitments under uncertain employment income.","outcomes":["Build a timeline for future commitments under uncertain employment income."],"situation":{"title":"Planning Beyond This Month in student life","body":"Final-year student Memory expects to graduate in four months. She estimates K800 for graduation-related travel and documents and has K200 saved. She hopes to find work quickly but has no job offer or start date. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Longer-term planning connects foreseeable commitments to dates and resources. Separate known costs from estimates and confirmed income from hopes. Preparing for work can involve transport, documents and communication costs before wages arrive. Compare a baseline plan with a delayed-income case. Break large commitments into smaller steps and review periodically. Support networks and information about opportunities can be part of a plan; employment is not guaranteed by budgeting.","takeaway":"Map future costs to dates.","definitions":[{"term":"Planning horizon","meaning":"The future period considered in a plan.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Scenario plan","meaning":"A plan that considers more than one possible outcome.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Remaining estimated cost: K800 − K200 = K600.","Over four months the target contribution is K150 monthly if affordable.","A delayed-job case must cover the period without assuming a salary. If K150 is unrealistic, revise costs or timing and explore support."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which plan handles uncertain employment responsibly?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Map future costs to dates.","consequence":"A delayed-job case must cover the period without assuming a salary. If K150 is unrealistic, revise costs or timing and explore support.","options":[{"text":"Plan graduation costs using current resources and test a delayed-job case","feedback":"It avoids treating hoped-for wages as confirmed funds."},{"text":"Commit the first salary before any job offer","feedback":"There is no confirmed amount or date."},{"text":"Ignore future costs because they are not due today","feedback":"Known commitments can be prepared for gradually."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"It avoids treating hoped-for wages as confirmed funds.","low":"There is no confirmed amount or date.","high":"Known commitments can be prepared for gradually."}},"checkpoint":[{"id":"lesson-6-1-q1","prompt":"What makes a future income estimate different from confirmed income?","options":[{"text":"It is always larger","feedback":"An estimate can be higher or lower."},{"text":"It never matters to planning","feedback":"It matters as a scenario, not as money already available."},{"text":"Its amount or arrival is not yet certain","feedback":"Uncertainty affects what commitments it can safely support."}],"correct":2,"explanation":"Uncertainty affects what commitments it can safely support."},{"id":"lesson-6-1-q2","prompt":"K1,000 goal, K400 saved and five months remaining require what monthly contribution?","options":[{"text":"K600","feedback":"That is the total gap."},{"text":"K120","feedback":"(K1,000 − K400) ÷ 5 = K120."},{"text":"K200","feedback":"That ignores existing savings."}],"correct":1,"explanation":"(K1,000 − K400) ÷ 5 = K120."},{"id":"lesson-6-1-q3","prompt":"A job start date is delayed. What should the plan do?","options":[{"text":"Revisit essential costs and the period before first pay","feedback":"The change affects cash-flow timing."},{"text":"Keep spending the expected salary","feedback":"The money has not arrived."},{"text":"Assume every future plan is useless","feedback":"Plans can be revised when circumstances change."}],"correct":0,"explanation":"The change affects cash-flow timing."}],"summaryTitle":"Bring the ideas together","takeaways":["Map future costs to dates.","Separate hopes from confirmed resources.","Prepare a delayed-income scenario."]}'::jsonb,content='Longer-term planning connects foreseeable commitments to dates and resources. Separate known costs from estimates and confirmed income from hopes. Preparing for work can involve transport, documents and communication costs before wages arrive. Compare a baseline plan with a delayed-income case. Break large commitments into smaller steps and review periodically. Support networks and information about opportunities can be part of a plan; employment is not guaranteed by budgeting.',revision=1,estimated_minutes=10,is_published=true where id=lid;
