if lid is null then lid:='ad439fd7-f112-4ba5-a8c5-c27eefc00cb8'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Inflation and Purchasing Power','',2); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-6-2","moduleId":"module-6","title":"Inflation and Purchasing Power","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Calculate how a fictional price change affects purchasing power."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for inflation and purchasing power"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"}],"introduction":"Calculate how a fictional price change affects purchasing power.","outcomes":["Calculate how a fictional price change affects purchasing power."],"situation":{"title":"Inflation and Purchasing Power in student life","body":"Last term, a fictional basket of study supplies cost K100. This term the same basket costs K110. Brian still has K500 for supplies and wonders whether an unchanged balance buys the same amount. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Purchasing power is what money can buy. Inflation is a sustained rise in the general price level; a single item’s price change alone is not the national inflation rate. If prices rise while your money stays the same, purchasing power falls. Compare the same quantities and quality over the same period. Nominal amounts are measured in money; real comparisons account for price changes. These examples do not state Zambia’s current inflation rate.","takeaway":"Distinguish money amounts from what they buy.","definitions":[{"term":"Purchasing power","meaning":"The goods and services an amount of money can buy.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Inflation","meaning":"An increase in the general level of prices over time.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Basket increase: K110 − K100 = K10, or 10% of K100.","K500 previously bought five baskets. Five now cost K550, a K50 gap.","Brian can buy four full baskets for K440 with K60 left, or adjust the mix. The example basket is not a national price index."],"showBudgetTable":false},"practice":{"kind":"numeric","prompt":"How much extra is needed for five baskets?","context":"The same basket rose from K100 to K110. Brian previously bought five baskets for K500. Calculate the additional money needed to buy five now.","correct":50,"explanation":"Five baskets now cost 5 × K110 = K550. K550 − K500 = K50 extra. The unchanged K500 has less purchasing power for this fictional basket.","unit":"K","hint":"Write down the known amounts, then choose the operations. Include all stated costs.","consequence":"Five baskets now cost 5 × K110 = K550. K550 − K500 = K50 extra. The unchanged K500 has less purchasing power for this fictional basket.","feedback":{"correctTitle":"The calculation is consistent","incorrectTitle":"Recheck the amounts","correct":"Five baskets now cost 5 × K110 = K550. K550 − K500 = K50 extra. The unchanged K500 has less purchasing power for this fictional basket.","low":"Your answer is below the required amount. Five baskets now cost 5 × K110 = K550. K550 − K500 = K50 extra. The unchanged K500 has less purchasing power for this fictional basket.","high":"Your answer is above the required amount. Five baskets now cost 5 × K110 = K550. K550 − K500 = K50 extra. The unchanged K500 has less purchasing power for this fictional basket."}},"checkpoint":[{"id":"lesson-6-2-q1","prompt":"Does one shop increasing one price prove the national inflation rate?","options":[{"text":"Only if the shop accepts mobile money","feedback":"Payment method does not determine inflation measurement."},{"text":"No; a general price measure covers a wider basket","feedback":"One price change is not the economy-wide measure."},{"text":"Yes, it equals that price increase","feedback":"That overgeneralises a single item."}],"correct":1,"explanation":"One price change is not the economy-wide measure."},{"id":"lesson-6-2-q2","prompt":"A fictional basket rises from K200 to K220. What is its percentage increase?","options":[{"text":"10%","feedback":"K20 ÷ K200 × 100 = 10%."},{"text":"20%","feedback":"K20 is the money increase, not the percentage."},{"text":"110%","feedback":"110% is the new price as a share of the old price, not the increase."}],"correct":0,"explanation":"K20 ÷ K200 × 100 = 10%."},{"id":"lesson-6-2-q3","prompt":"Savings rise 5% while the relevant basket rises 10%. What follows?","options":[{"text":"Purchasing power must rise because the balance rose","feedback":"Real purchasing power depends on both changes."},{"text":"All savings were lost","feedback":"Reduced purchasing power is not the same as losing the whole balance."},{"text":"The savings buy less of that basket despite increasing in kwacha","feedback":"Prices grew faster than the nominal balance."}],"correct":2,"explanation":"Prices grew faster than the nominal balance."}],"summaryTitle":"Bring the ideas together","takeaways":["Distinguish money amounts from what they buy.","Use comparable prices and quantities.","A single price change is not national inflation."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
