if lid is null then lid:='75a02166-4824-49ad-a6f5-a92d7b54a690'::uuid; insert into public.lessons(id,module_id,title,content,sort_order) values(lid,mid,'Financial Risk and Return','',3); end if;
if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-6-3","moduleId":"module-6","title":"Financial Risk and Return","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","ilo"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Compare uncertain outcomes against a goal’s timing and loss capacity."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for financial risk and return"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"ilo","section":"Session 6: Risk management and insurance","concept":"Insurance as protection for specified losses, distinct from investment returns"}],"introduction":"Compare uncertain outcomes against a goal’s timing and loss capacity.","outcomes":["Compare uncertain outcomes against a goal’s timing and loss capacity."],"situation":{"title":"Financial Risk and Return in student life","body":"Zola has K600 needed for registration in two months. A fictional investment could be worth K720 or K480 at that time. A friend describes only the higher outcome. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Saving sets money aside for later use; investing commits capital, the initial funds, to assets with uncertain gains or losses. Return is the gain or loss on an investment, including relevant costs. Risk includes the possibility of losing value or being unable to access money when needed. Higher promised returns do not guarantee better outcomes; claims should be examined. Time horizon and capacity to bear loss matter. Diversification spreads exposure across different investments, but cannot remove every risk. Money needed soon for essentials requires particular attention to security and access. Insurance is another form of risk protection: a premium pays for cover against specified losses under policy conditions. Exclusions, excess amounts and claim requirements matter. Insurance does not make an investment risk-free. This lesson explains concepts rather than recommending a product.","takeaway":"Consider losses as well as gains.","definitions":[{"term":"Return","meaning":"Gain or loss relative to the amount invested.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Risk","meaning":"Uncertainty about outcomes, including loss or unavailable funds.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Diversification","meaning":"Spreading exposure rather than depending entirely on one investment.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Higher outcome: K720 − K600 = K120 gain, or 20%.","Lower outcome: K480 − K600 = −K120, a 20% loss.","The lower outcome leaves registration K120 short. The possible gain does not remove that essential-cost risk."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which issue should Zola consider first?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Consider losses as well as gains.","consequence":"The lower outcome leaves registration K120 short. The possible gain does not remove that essential-cost risk.","options":[{"text":"Whether she can still fund registration if the value falls or access is delayed","feedback":"The goal is soon and essential; the downside matters."},{"text":"Only the possible K120 gain","feedback":"That ignores loss and access risk."},{"text":"Assume a friend’s confidence guarantees returns","feedback":"Confidence is not a guarantee or evidence."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The goal is soon and essential; the downside matters.","low":"That ignores loss and access risk.","high":"Confidence is not a guarantee or evidence."}},"checkpoint":[{"id":"lesson-6-3-q1","prompt":"Does diversification eliminate every investment risk?","options":[{"text":"No, it spreads exposure but losses can still occur","feedback":"Different investments can still be affected by shared risks."},{"text":"Yes, all losses become impossible","feedback":"Diversification is not insurance against every loss."},{"text":"It means putting everything in one offer","feedback":"That concentrates rather than spreads exposure."}],"correct":0,"explanation":"Different investments can still be affected by shared risks."},{"id":"lesson-6-3-q2","prompt":"A fictional K400 investment becomes K440 before fees. What is the gain?","options":[{"text":"K440 or 110% gain","feedback":"K440 includes the original principal."},{"text":"K4 or 1%","feedback":"The difference is K40."},{"text":"K40 or 10%","feedback":"K440 − K400 = K40; K40 ÷ K400 = 10%."}],"correct":2,"explanation":"K440 − K400 = K40; K40 ÷ K400 = 10%."},{"id":"lesson-6-3-q3","prompt":"Why does needing money next week matter?","options":[{"text":"Risk depends only on the investment’s name","feedback":"Terms, outcomes and personal capacity matter."},{"text":"A loss or withdrawal delay may prevent paying the essential cost","feedback":"Timing and liquidity are part of suitability."},{"text":"Short deadlines guarantee higher returns","feedback":"They do not guarantee returns."}],"correct":1,"explanation":"Timing and liquidity are part of suitability."}],"summaryTitle":"Bring the ideas together","takeaways":["Consider losses as well as gains.","Match access and risk to the deadline.","Diversification reduces concentration, not every risk."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-6-3',title='Financial Risk and Return',summary='Compare uncertain outcomes against a goal’s timing and loss capacity.',structured_content='{"id":"lesson-6-3","moduleId":"module-6","title":"Financial Risk and Return","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","ilo"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Compare uncertain outcomes against a goal’s timing and loss capacity."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for financial risk and return"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"ilo","section":"Session 6: Risk management and insurance","concept":"Insurance as protection for specified losses, distinct from investment returns"}],"introduction":"Compare uncertain outcomes against a goal’s timing and loss capacity.","outcomes":["Compare uncertain outcomes against a goal’s timing and loss capacity."],"situation":{"title":"Financial Risk and Return in student life","body":"Zola has K600 needed for registration in two months. A fictional investment could be worth K720 or K480 at that time. A friend describes only the higher outcome. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"Saving sets money aside for later use; investing commits capital, the initial funds, to assets with uncertain gains or losses. Return is the gain or loss on an investment, including relevant costs. Risk includes the possibility of losing value or being unable to access money when needed. Higher promised returns do not guarantee better outcomes; claims should be examined. Time horizon and capacity to bear loss matter. Diversification spreads exposure across different investments, but cannot remove every risk. Money needed soon for essentials requires particular attention to security and access. Insurance is another form of risk protection: a premium pays for cover against specified losses under policy conditions. Exclusions, excess amounts and claim requirements matter. Insurance does not make an investment risk-free. This lesson explains concepts rather than recommending a product.","takeaway":"Consider losses as well as gains.","definitions":[{"term":"Return","meaning":"Gain or loss relative to the amount invested.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Risk","meaning":"Uncertainty about outcomes, including loss or unavailable funds.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Diversification","meaning":"Spreading exposure rather than depending entirely on one investment.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Higher outcome: K720 − K600 = K120 gain, or 20%.","Lower outcome: K480 − K600 = −K120, a 20% loss.","The lower outcome leaves registration K120 short. The possible gain does not remove that essential-cost risk."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which issue should Zola consider first?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Consider losses as well as gains.","consequence":"The lower outcome leaves registration K120 short. The possible gain does not remove that essential-cost risk.","options":[{"text":"Whether she can still fund registration if the value falls or access is delayed","feedback":"The goal is soon and essential; the downside matters."},{"text":"Only the possible K120 gain","feedback":"That ignores loss and access risk."},{"text":"Assume a friend’s confidence guarantees returns","feedback":"Confidence is not a guarantee or evidence."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The goal is soon and essential; the downside matters.","low":"That ignores loss and access risk.","high":"Confidence is not a guarantee or evidence."}},"checkpoint":[{"id":"lesson-6-3-q1","prompt":"Does diversification eliminate every investment risk?","options":[{"text":"No, it spreads exposure but losses can still occur","feedback":"Different investments can still be affected by shared risks."},{"text":"Yes, all losses become impossible","feedback":"Diversification is not insurance against every loss."},{"text":"It means putting everything in one offer","feedback":"That concentrates rather than spreads exposure."}],"correct":0,"explanation":"Different investments can still be affected by shared risks."},{"id":"lesson-6-3-q2","prompt":"A fictional K400 investment becomes K440 before fees. What is the gain?","options":[{"text":"K440 or 110% gain","feedback":"K440 includes the original principal."},{"text":"K4 or 1%","feedback":"The difference is K40."},{"text":"K40 or 10%","feedback":"K440 − K400 = K40; K40 ÷ K400 = 10%."}],"correct":2,"explanation":"K440 − K400 = K40; K40 ÷ K400 = 10%."},{"id":"lesson-6-3-q3","prompt":"Why does needing money next week matter?","options":[{"text":"Risk depends only on the investment’s name","feedback":"Terms, outcomes and personal capacity matter."},{"text":"A loss or withdrawal delay may prevent paying the essential cost","feedback":"Timing and liquidity are part of suitability."},{"text":"Short deadlines guarantee higher returns","feedback":"They do not guarantee returns."}],"correct":1,"explanation":"Timing and liquidity are part of suitability."}],"summaryTitle":"Bring the ideas together","takeaways":["Consider losses as well as gains.","Match access and risk to the deadline.","Diversification reduces concentration, not every risk."]}'::jsonb,content='Saving sets money aside for later use; investing commits capital, the initial funds, to assets with uncertain gains or losses. Return is the gain or loss on an investment, including relevant costs. Risk includes the possibility of losing value or being unable to access money when needed. Higher promised returns do not guarantee better outcomes; claims should be examined. Time horizon and capacity to bear loss matter. Diversification spreads exposure across different investments, but cannot remove every risk. Money needed soon for essentials requires particular attention to security and access. Insurance is another form of risk protection: a premium pays for cover against specified losses under policy conditions. Exclusions, excess amounts and claim requirements matter. Insurance does not make an investment risk-free. This lesson explains concepts rather than recommending a product.',revision=1,estimated_minutes=10,is_published=true where id=lid;
