if exists(select 1 from public.lesson_progress where lesson_id=lid and player_state is not null) and exists(select 1 from public.lessons where id=lid and structured_content is distinct from '{"id":"lesson-6-4","moduleId":"module-6","title":"Evaluating Investment Claims","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","sec"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Identify warning signs and verify an investment claim independently."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for evaluating investment claims"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"sec","section":"Public warning dated 21 February 2023","concept":"Verify investment adviser authorisation independently"}],"introduction":"Identify warning signs and verify an investment claim independently.","outcomes":["Identify warning signs and verify an investment claim independently."],"situation":{"title":"Evaluating Investment Claims in student life","body":"A social-media group promises to turn K300 into K900 in seven days with “no risk”. Participants must recruit friends and pay a personal mobile-money number. The organiser sends a registration image but refuses written withdrawal terms. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"An investment claim needs evidence about how returns arise, who is responsible, costs, withdrawal conditions and risks. Guaranteed unusually high returns, pressure, recruitment rewards and unexplained payment destinations are warning signs. A registration image or testimonial can be copied and does not establish permission to offer an investment. Check the relevant regulator’s official register and contact details independently; for securities-related offers in Zambia, consult the Securities and Exchange Commission. Even a licensed provider does not guarantee investment returns. Do not send more money to “unlock” an unverified payout.","takeaway":"Treat promises as claims requiring evidence.","definitions":[{"term":"Due diligence","meaning":"Checking evidence and conditions before committing money.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Investment claim","meaning":"A statement about expected returns or benefits that needs verification.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Claimed gain: K900 − K300 = K600, or 200% in seven days.","The arithmetic describes the promise, not proof that it is achievable.","Pause payment, verify the operator and offer independently, and examine written risks and withdrawal terms. Refusal to explain is a reason not to proceed."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which response best evaluates the offer?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Treat promises as claims requiring evidence.","consequence":"Pause payment, verify the operator and offer independently, and examine written risks and withdrawal terms. Refusal to explain is a reason not to proceed.","options":[{"text":"Pause and verify authorisation, return mechanism and written conditions independently","feedback":"The warning signs require evidence, not an urgent payment."},{"text":"Recruit friends to test whether it works","feedback":"That exposes others to the same unverified risk."},{"text":"Pay because the registration image looks official","feedback":"An image may be copied and may not authorise this activity."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The warning signs require evidence, not an urgent payment.","low":"That exposes others to the same unverified risk.","high":"An image may be copied and may not authorise this activity."}},"checkpoint":[{"id":"lesson-6-4-q1","prompt":"Which combination is a warning sign?","options":[{"text":"Clear written risks and terms","feedback":"Disclosure supports assessment, though it is not a guarantee."},{"text":"Time to consider an offer","feedback":"Time allows verification rather than pressure."},{"text":"No-risk high returns plus pressure to recruit","feedback":"These claims warrant independent checking and caution."}],"correct":2,"explanation":"These claims warrant independent checking and caution."},{"id":"lesson-6-4-q2","prompt":"K200 is promised to become K500. What gain is claimed?","options":[{"text":"K700","feedback":"Adding the two figures overstates the promised payout."},{"text":"K300","feedback":"K500 − K200 = K300; calculating it does not validate the promise."},{"text":"K500","feedback":"That includes the original amount."}],"correct":1,"explanation":"K500 − K200 = K300; calculating it does not validate the promise."},{"id":"lesson-6-4-q3","prompt":"What does a verified licence establish?","options":[{"text":"Authorisation for specified activities, not guaranteed returns","feedback":"Check the scope and offer; losses may still occur."},{"text":"Every product is risk-free","feedback":"Licensing does not remove market or other risks."},{"text":"A stranger may request your PIN","feedback":"Credentials must remain private regardless of claimed status."}],"correct":0,"explanation":"Check the scope and offer; losses may still occur."}],"summaryTitle":"Bring the ideas together","takeaways":["Treat promises as claims requiring evidence.","Verify authorisation through independent official channels.","Do not confuse licensing with guaranteed returns."]}'::jsonb) then raise exception 'Lesson content changed after progress: author a revision migration'; end if;
update public.lessons set content_key='lesson-6-4',title='Evaluating Investment Claims',summary='Identify warning signs and verify an investment claim independently.',structured_content='{"id":"lesson-6-4","moduleId":"module-6","title":"Evaluating Investment Claims","version":1,"estimatedMinutes":10,"sourceStatus":"reviewed","citations":["nsfe","oecd","worldbank","finscope","toolkit","sec"],"references":[{"source":"nsfe","section":"Priority programmes for children and youth; tertiary education","concept":"Practical financial capability for students"},{"source":"oecd","section":"Money and transactions; risk and reward; financial landscape","concept":"Identify warning signs and verify an investment claim independently."},{"source":"worldbank","section":"Financial capability and its relationship with inclusion","concept":"Zambian context for evaluating investment claims"},{"source":"finscope","section":"7.4 Assets and Asset Building; 10.3 Financial Literacy","concept":"Context for original student scenarios, not current product claims"},{"source":"toolkit","section":"Knowledge, behaviour and attitudes","concept":"Checkpoint design: understanding, application and reasoning"},{"source":"sec","section":"Public warning dated 21 February 2023","concept":"Verify investment adviser authorisation independently"}],"introduction":"Identify warning signs and verify an investment claim independently.","outcomes":["Identify warning signs and verify an investment claim independently."],"situation":{"title":"Evaluating Investment Claims in student life","body":"A social-media group promises to turn K300 into K900 in seven days with “no risk”. Participants must recruit friends and pay a personal mobile-money number. The organiser sends a registration image but refuses written withdrawal terms. All amounts and people in this lesson are fictional.","figures":[],"reflection":"What would you check before making this decision?","choices":["Available resources and obligations","The timing and consequences","Information that still needs verification"]},"concept":{"title":"Understand the decision","introduction":"An investment claim needs evidence about how returns arise, who is responsible, costs, withdrawal conditions and risks. Guaranteed unusually high returns, pressure, recruitment rewards and unexplained payment destinations are warning signs. A registration image or testimonial can be copied and does not establish permission to offer an investment. Check the relevant regulator’s official register and contact details independently; for securities-related offers in Zambia, consult the Securities and Exchange Commission. Even a licensed provider does not guarantee investment returns. Do not send more money to “unlock” an unverified payout.","takeaway":"Treat promises as claims requiring evidence.","definitions":[{"term":"Due diligence","meaning":"Checking evidence and conditions before committing money.","detail":"Apply this distinction to the situation and worked example before choosing your response."},{"term":"Investment claim","meaning":"A statement about expected returns or benefits that needs verification.","detail":"Apply this distinction to the situation and worked example before choosing your response."}]},"example":{"title":"Work through the situation","introduction":"Follow the reasoning. These figures illustrate the decision; they are not current prices, fees or product recommendations.","income":0,"rows":[],"steps":["Claimed gain: K900 − K300 = K600, or 200% in seven days.","The arithmetic describes the promise, not proof that it is achievable.","Pause payment, verify the operator and offer independently, and examine written risks and withdrawal terms. Refusal to explain is a reason not to proceed."],"showBudgetTable":false},"practice":{"kind":"choice","prompt":"Which response best evaluates the offer?","context":"Use the information in the situation. Choose a response, then examine its consequences.","correct":0,"unit":"","hint":"Treat promises as claims requiring evidence.","consequence":"Pause payment, verify the operator and offer independently, and examine written risks and withdrawal terms. Refusal to explain is a reason not to proceed.","options":[{"text":"Pause and verify authorisation, return mechanism and written conditions independently","feedback":"The warning signs require evidence, not an urgent payment."},{"text":"Recruit friends to test whether it works","feedback":"That exposes others to the same unverified risk."},{"text":"Pay because the registration image looks official","feedback":"An image may be copied and may not authorise this activity."}],"feedback":{"correctTitle":"Your decision accounts for the constraint","incorrectTitle":"Consider the consequence","correct":"The warning signs require evidence, not an urgent payment.","low":"That exposes others to the same unverified risk.","high":"An image may be copied and may not authorise this activity."}},"checkpoint":[{"id":"lesson-6-4-q1","prompt":"Which combination is a warning sign?","options":[{"text":"Clear written risks and terms","feedback":"Disclosure supports assessment, though it is not a guarantee."},{"text":"Time to consider an offer","feedback":"Time allows verification rather than pressure."},{"text":"No-risk high returns plus pressure to recruit","feedback":"These claims warrant independent checking and caution."}],"correct":2,"explanation":"These claims warrant independent checking and caution."},{"id":"lesson-6-4-q2","prompt":"K200 is promised to become K500. What gain is claimed?","options":[{"text":"K700","feedback":"Adding the two figures overstates the promised payout."},{"text":"K300","feedback":"K500 − K200 = K300; calculating it does not validate the promise."},{"text":"K500","feedback":"That includes the original amount."}],"correct":1,"explanation":"K500 − K200 = K300; calculating it does not validate the promise."},{"id":"lesson-6-4-q3","prompt":"What does a verified licence establish?","options":[{"text":"Authorisation for specified activities, not guaranteed returns","feedback":"Check the scope and offer; losses may still occur."},{"text":"Every product is risk-free","feedback":"Licensing does not remove market or other risks."},{"text":"A stranger may request your PIN","feedback":"Credentials must remain private regardless of claimed status."}],"correct":0,"explanation":"Check the scope and offer; losses may still occur."}],"summaryTitle":"Bring the ideas together","takeaways":["Treat promises as claims requiring evidence.","Verify authorisation through independent official channels.","Do not confuse licensing with guaranteed returns."]}'::jsonb,content='An investment claim needs evidence about how returns arise, who is responsible, costs, withdrawal conditions and risks. Guaranteed unusually high returns, pressure, recruitment rewards and unexplained payment destinations are warning signs. A registration image or testimonial can be copied and does not establish permission to offer an investment. Check the relevant regulator’s official register and contact details independently; for securities-related offers in Zambia, consult the Securities and Exchange Commission. Even a licensed provider does not guarantee investment returns. Do not send more money to “unlock” an unverified payout.',revision=1,estimated_minutes=10,is_published=true where id=lid;
